//! SQL statement compiler for the VM engine
//!
//! This module is responsible for compiling SQL statements parsed by sqlparser
//! into bytecode instructions that can be executed by the SQL VM.
//! It implements a visitor pattern to walk the AST generated by sqlparser.

use super::ast_compat::{
    create_table_options, delete_from, func_args, func_is_distinct, group_by_exprs, insert_target,
    is_group_by_all, is_order_by_all, object_name_last, order_by_is_asc, query_limit, query_offset,
    query_order_by,
};
use sqlparser::ast::{
    BinaryOperator, CaseWhen, DataType as SqlDataType, Expr, Function, FunctionArg,
    FunctionArgExpr, Ident, ObjectName, OrderByExpr, Query, Select, SelectItem,
    SelectItemQualifiedWildcardKind, SetExpr, SetOperator, SetQuantifier, Statement, UnaryOperator,
    Value, ValueWithSpan,
};
use sqlparser::dialect::HiveDialect;
use sqlparser::parser::Parser;
use std::collections::HashMap;

use super::bytecode::{
    Instruction, OpCode, Program, ResultSchema, AGG_AVG, AGG_COUNT, AGG_DISTINCT, AGG_MAX, AGG_MIN,
    AGG_SUM,
};
use super::compiler_from::{expr_children, FromPlan};
use crate::aggregate::AggregateFunction;
use crate::capacity::DEFAULT_CURSOR_CAPACITY;
use crate::database::Database;
use crate::error::{SqawkError, SqawkResult};
use crate::table::{DataType, Table, Value as TableValue};

/// Outer column reference found in a correlated subquery (Phase 4B)
#[derive(Debug, Clone)]
struct OuterColumnRef {
    /// The table qualifier (alias or table name) the outer query used.
    ///
    /// Only the qualifier is needed: which column it names is resolved by
    /// NameCtx against the outer table, so recording it here would be a second
    /// copy of that lookup.
    qualifier: String,
}

/// A symbolic jump target.
///
/// Jump destinations used to be computed arithmetically, as offsets from
/// `program.len()` counting instructions that had not been emitted yet -- e.g.
/// `let skip_offset = if limit_reg.is_some() { 3 } else { 2 }`. That couples
/// every jump to the exact shape of the code after it, so inserting,
/// reordering, or conditionally omitting an instruction silently retargets the
/// jump. The failure mode is a wrong answer, not a crash.
///
/// A `Label` is created before it is known where it points, used as a jump
/// destination any number of times, and bound to an address later with
/// [`SqlCompiler::resolve`]. Unresolved labels are a compile-time bug and are
/// caught by an assertion when the program is finished.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct Label(usize);

/// One FROM source visible to expression compilation.
#[derive(Clone)]
pub(crate) struct Src<'t> {
    /// VM cursor id for this source.
    pub cursor: i64,
    /// The table behind the cursor.
    pub table: &'t Table,
    /// How the query refers to it: the alias if there is one, else the table
    /// name. Stored ASCII-lowercased, since SQL identifiers are matched
    /// case-insensitively.
    pub refname: String,
}

/// One output column of a SELECT list, after `*` expansion.
pub(crate) struct OutCol {
    /// The value, as an expression over the FROM sources.
    pub expr: Expr,
    /// Result header.
    pub name: String,
    /// The `AS` alias, which ORDER BY may name.
    pub alias: Option<String>,
}

/// A column merged by `JOIN ... USING (col)` or NATURAL JOIN.
///
/// SQL gives such a join ONE output column per USING name, so an unqualified
/// reference is not ambiguous even though both tables have the column. Its
/// value is the first non-NULL of the joined columns, which for an inner or
/// LEFT join is simply the left table's value and for RIGHT/FULL picks up the
/// right side's value on NULL-extended rows.
#[derive(Clone, Debug)]
pub(crate) struct UsingCol {
    /// Column name, ASCII-lowercased.
    pub name: String,
    /// The merged columns as (cursor, column index), leftmost first.
    pub refs: Vec<(i64, usize)>,
}

/// A resolved column: where its value lives at run time.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ColumnRef {
    /// Read column `col` from cursor `cursor`.
    Cursor { cursor: i64, col: usize },
    /// The value is already in this register.
    Register(i64),
    /// A USING-merged column: index into [`NameCtx::using`].
    Using(usize),
}

/// Name resolution scope for [`SqlCompiler::code_expr`].
///
/// The reason two expression compilers drifted apart is that both threaded a
/// bare `(table, cursor_idx)` pair, a shape that cannot express a join, an
/// alias, or a post-aggregation scope. Everything a name can resolve against
/// lives here instead, so one compiler serves the SELECT list, WHERE, HAVING,
/// ORDER BY and SET clauses.
pub(crate) struct NameCtx<'t> {
    /// FROM sources in cursor order. Empty for `SELECT 1` (no FROM).
    pub srcs: Vec<Src<'t>>,

    /// Enclosing query's sources, for a correlated subquery.
    ///
    /// SQL resolves a name in the innermost scope first and only then looks
    /// outward, so these are consulted only when `srcs` has no match. Keeping
    /// them in a separate list rather than appending to `srcs` preserves that
    /// precedence, and keeps the ambiguity check meaningful: two tables in one
    /// FROM are ambiguous, but an inner name shadowing an outer one is not.
    pub outer: Vec<Src<'t>>,

    /// Values already computed into registers, keyed by the rendered
    /// expression text (`"sum(salary)"`, or a GROUP BY key such as
    /// `"upper(department)"`).
    ///
    /// After aggregation an aggregate is a value like any other, so an
    /// expression may contain one -- `SUM(salary) + 1`. Binding them here lets
    /// the ordinary expression compiler handle the surrounding arithmetic
    /// instead of needing a separate post-aggregation compiler.
    pub agg_bindings: Vec<(String, i64)>,

    /// Columns merged by USING / NATURAL JOIN.
    pub using: Vec<UsingCol>,

    /// Post-aggregation column scope.
    ///
    /// `None` for an ordinary row scope. `Some` once rows have been grouped:
    /// only GROUP BY key columns still have a single value per output row, so
    /// a column reference must be one of these (bound to the register holding
    /// the key) or it is an error -- reading the cursor at that point would
    /// return whatever row the scan happened to stop on.
    pub col_bindings: Option<Vec<(ColumnRef, i64)>>,
}

impl<'t> NameCtx<'t> {
    /// The common single-table scope, equivalent to the old
    /// `(table, cursor_idx)` pair.
    pub(crate) fn single(table: &'t Table, cursor: i64) -> Self {
        Self::multi(vec![Src {
            cursor,
            table,
            refname: table.name().to_ascii_lowercase(),
        }])
    }

    /// A scope over several FROM sources, for joins.
    pub(crate) fn multi(srcs: Vec<Src<'t>>) -> Self {
        NameCtx {
            srcs,
            outer: Vec::new(),
            agg_bindings: Vec::new(),
            using: Vec::new(),
            col_bindings: None,
        }
    }

    /// A scope with no FROM sources, for constant expressions.
    pub(crate) fn empty() -> Self {
        Self::multi(Vec::new())
    }

    /// Normalized key for an aggregate call, used to bind and to look up.
    pub(crate) fn agg_key(expr: &Expr) -> String {
        expr.to_string().to_ascii_lowercase()
    }

    /// Register holding an already-computed value for `expr`, if bound.
    fn lookup_agg(&self, expr: &Expr) -> Option<i64> {
        if self.agg_bindings.is_empty() {
            return None;
        }
        let key = Self::agg_key(expr);
        self.agg_bindings
            .iter()
            .find(|(k, _)| *k == key)
            .map(|(_, r)| *r)
    }

    /// Apply the post-aggregation scope to a resolved column.
    fn bind(&self, col: ColumnRef, name: &str) -> SqawkResult<ColumnRef> {
        match &self.col_bindings {
            None => Ok(col),
            Some(bound) => bound
                .iter()
                .find(|(c, _)| *c == col)
                .map(|(_, reg)| ColumnRef::Register(*reg))
                .ok_or_else(|| {
                    SqawkError::InvalidSqlQuery(format!(
                        "'{}' must appear in GROUP BY or be used in an aggregate",
                        name
                    ))
                }),
        }
    }

    /// Resolve an unqualified column name across every source.
    ///
    /// Case-insensitive: `SELECT NAME` already worked while
    /// `WHERE NAME = 'x'` did not, because the projection path lowercased and
    /// `find_column_index` compared exactly.
    ///
    /// Returns `Err` if no source has the column, or if more than one does --
    /// silently picking the first would make the result depend on FROM order.
    /// A USING-merged column is the exception: it is one column by definition.
    pub(crate) fn resolve_unqualified(&self, name: &str) -> SqawkResult<ColumnRef> {
        let want = name.to_ascii_lowercase();
        if let Some(i) = self.using.iter().position(|u| u.name == want) {
            return Ok(ColumnRef::Using(i));
        }
        let mut found: Option<ColumnRef> = None;
        for src in &self.srcs {
            for (i, col) in src.table.column_metadata().iter().enumerate() {
                if col.name.to_ascii_lowercase() == want {
                    if found.is_some() {
                        return Err(SqawkError::InvalidSqlQuery(format!(
                            "Column '{}' is ambiguous across the tables in FROM",
                            name
                        )));
                    }
                    found = Some(ColumnRef::Cursor {
                        cursor: src.cursor,
                        col: i,
                    });
                    break;
                }
            }
        }
        if let Some(col) = found {
            return Ok(col);
        }
        // Not in this scope: look outward, nearest first.
        for src in &self.outer {
            for (i, col) in src.table.column_metadata().iter().enumerate() {
                if col.name.to_ascii_lowercase() == want {
                    return Ok(ColumnRef::Cursor {
                        cursor: src.cursor,
                        col: i,
                    });
                }
            }
        }
        Err(SqawkError::ColumnNotFound(name.to_string()))
    }

    /// Resolve a `table.column` (or `alias.column`) reference.
    pub(crate) fn resolve_qualified(&self, qualifier: &str, name: &str) -> SqawkResult<ColumnRef> {
        let qual = qualifier.to_ascii_lowercase();
        let want = name.to_ascii_lowercase();
        for src in self.srcs.iter().chain(&self.outer) {
            if src.refname != qual {
                continue;
            }
            for (i, col) in src.table.column_metadata().iter().enumerate() {
                if col.name.to_ascii_lowercase() == want {
                    return Ok(ColumnRef::Cursor {
                        cursor: src.cursor,
                        col: i,
                    });
                }
            }
            return Err(SqawkError::ColumnNotFound(format!(
                "{}.{}",
                qualifier, name
            )));
        }
        // Unknown qualifier entirely. With a single source, fall back to an
        // unqualified match so `employees.age` still works when the table was
        // given an alias. With several, a wrong qualifier is an error: the
        // fallback could silently read the same-named column of another table.
        if self.srcs.len() <= 1 {
            return self.resolve_unqualified(name);
        }
        Err(SqawkError::ColumnNotFound(format!(
            "{}.{}",
            qualifier, name
        )))
    }
}

/// Validate the argument count of a math function (ABS, ROUND, CEIL,
/// CEILING, FLOOR).
///
/// Without it, extra arguments were silently ignored: `SELECT ABS(-5, 2)`
/// quietly returned 5.
fn check_math_func_arity(func_name: &str, arg_count: usize) -> SqawkResult<()> {
    if arg_count == 0 {
        return Err(SqawkError::InvalidSqlQuery(format!(
            "{} requires one argument",
            func_name
        )));
    }

    // ROUND is the only one of these taking an optional precision argument.
    let max_args = if func_name == "ROUND" { 2 } else { 1 };
    if arg_count > max_args {
        return Err(SqawkError::InvalidSqlQuery(if max_args == 1 {
            format!("{} takes exactly one argument", func_name)
        } else {
            format!("{} takes at most two arguments", func_name)
        }));
    }

    Ok(())
}

/// Reject a scale or TO-datetime argument on CEIL/FLOOR.
///
/// sqlparser lowers `CEIL`/`FLOOR` to [`sqlparser::ast::Expr::Ceil`] and
/// [`sqlparser::ast::Expr::Floor`] rather than `Expr::Function`, carrying any
/// second argument in `field` instead of an argument list. They therefore miss
/// [`check_math_func_arity`] entirely, and `CEIL(1.2, 3)` used to return 2
/// while the `CEILING(1.2, 3)` spelling of the same call was rejected.
fn check_ceil_floor_field(
    func_name: &str,
    field: &sqlparser::ast::CeilFloorKind,
) -> SqawkResult<()> {
    use sqlparser::ast::{CeilFloorKind, DateTimeField};
    match field {
        CeilFloorKind::DateTimeField(DateTimeField::NoDateTime) => Ok(()),
        _ => Err(SqawkError::InvalidSqlQuery(format!(
            "{} takes exactly one argument",
            func_name
        ))),
    }
}

/// SQL statement compiler that generates bytecode for the VM engine
pub struct SqlCompiler<'a> {
    /// The database containing tables
    pub(crate) database: &'a Database,

    /// Name mapping for tables referenced in the query
    pub(crate) table_map: HashMap<String, String>,

    /// Current bytecode program being generated
    pub(crate) program: Program,

    /// Counter for register allocation
    pub(crate) register_counter: i64,

    /// Whether to generate verbose bytecode with detailed comments
    pub(crate) verbose: bool,

    /// Current outer table alias for correlated subquery detection
    pub(crate) current_outer_alias: Option<String>,

    /// Resolved address of each label, indexed by label id. `None` until
    /// [`SqlCompiler::resolve`] binds it.
    label_addrs: Vec<Option<usize>>,

    /// Jumps awaiting resolution: (instruction address, target label).
    pending_jumps: Vec<(usize, Label)>,

    /// Three-way `Jump`s awaiting resolution:
    /// (instruction address, less, equal, greater).
    pending_jumps_three: Vec<(usize, Label, Label, Label)>,
}

impl<'a> SqlCompiler<'a> {
    /// Create a new SQL compiler
    pub fn new(database: &'a Database, verbose: bool) -> Self {
        SqlCompiler {
            database,
            table_map: HashMap::with_capacity(DEFAULT_CURSOR_CAPACITY),
            program: Program::new(),
            register_counter: 0,
            verbose,
            current_outer_alias: None,
            label_addrs: Vec::new(),
            pending_jumps: Vec::new(),
            pending_jumps_three: Vec::new(),
        }
    }

    /// Create a new, unresolved jump target.
    pub(crate) fn label(&mut self) -> Label {
        self.label_addrs.push(None);
        Label(self.label_addrs.len() - 1)
    }

    /// Bind `label` to the next instruction to be emitted.
    ///
    /// Panics if the label was already resolved -- a label denotes exactly one
    /// address, and rebinding one silently redirects every jump to it.
    pub(crate) fn resolve(&mut self, label: Label) {
        let addr = self.program.len();
        debug_assert!(
            self.label_addrs[label.0].is_none(),
            "label {:?} resolved twice (already at {:?}, now {})",
            label,
            self.label_addrs[label.0],
            addr
        );
        self.label_addrs[label.0] = Some(addr);
    }

    /// Emit a jump instruction whose destination (p2) is `target`.
    ///
    /// The destination is patched in by [`SqlCompiler::finish_labels`], so the
    /// target may be resolved before or after this call.
    pub(crate) fn emit_jump_to(
        &mut self,
        opcode: OpCode,
        p1: i64,
        target: Label,
        p3: i64,
        p4: Option<String>,
        comment: &str,
    ) {
        let addr = self.program.len();
        // p2 is a placeholder; finish_labels overwrites it.
        self.emit(opcode, p1, -1, p3, p4, comment);
        self.pending_jumps.push((addr, target));
    }

    /// Emit a `Jump`: a three-way branch on the most recent `Compare`.
    ///
    /// All three destinations are labels, patched by `finish_labels`.
    pub(crate) fn emit_jump_to_three(
        &mut self,
        less: Label,
        equal: Label,
        greater: Label,
        comment: &str,
    ) {
        let addr = self.program.len();
        self.emit(OpCode::Jump, -1, -1, -1, None, comment);
        self.pending_jumps_three.push((addr, less, equal, greater));
    }

    /// Patch every pending jump with its label's address.
    ///
    /// Called once when a program is finished. An unresolved label means a
    /// code path forgot to mark its destination, which would leave a jump
    /// pointing at the placeholder -- so it fails loudly rather than
    /// generating a program that runs and returns nonsense.
    pub(crate) fn finish_labels(&mut self) -> SqawkResult<()> {
        for (addr, label) in std::mem::take(&mut self.pending_jumps) {
            let target = self.label_addrs[label.0].ok_or_else(|| {
                SqawkError::InvalidSqlQuery(format!(
                    "internal error: jump at {} targets unresolved label {:?}",
                    addr, label
                ))
            })?;
            self.patch_jump(addr, target);
        }
        for (addr, less, equal, greater) in std::mem::take(&mut self.pending_jumps_three) {
            let resolve = |l: Label| -> SqawkResult<i64> {
                self.label_addrs[l.0].map(|a| a as i64).ok_or_else(|| {
                    SqawkError::InvalidSqlQuery(format!(
                        "internal error: Jump at {} targets unresolved label {:?}",
                        addr, l
                    ))
                })
            };
            let (p1, p2, p3) = (resolve(less)?, resolve(equal)?, resolve(greater)?);
            if let Some(inst) = self.program.instructions.get_mut(addr) {
                inst.p1 = p1;
                inst.p2 = p2;
                inst.p3 = p3;
            }
        }
        self.label_addrs.clear();
        Ok(())
    }

    /// Allocate a new register and return its index
    pub(crate) fn allocate_register(&mut self) -> i64 {
        let reg = self.register_counter;
        self.register_counter += 1;
        reg
    }

    /// Allocate multiple consecutive registers and return the starting index
    pub(crate) fn allocate_registers(&mut self, count: usize) -> i64 {
        let start = self.allocate_register();
        for _ in 1..count {
            self.allocate_register();
        }
        start
    }

    /// Reset the register counter (used between statements)
    fn reset_registers(&mut self) {
        self.register_counter = 0;
    }

    /// Helper method to emit an instruction
    pub(crate) fn emit(
        &mut self,
        opcode: OpCode,
        p1: i64,
        p2: i64,
        p3: i64,
        p4: Option<String>,
        comment: &str,
    ) {
        self.program.add_instruction(Instruction::new(
            opcode,
            p1,
            p2,
            p3,
            p4,
            0,
            Some(comment.to_string()),
        ));
    }

    /// The AggStep/AggFinal function-type word for an aggregate CALL,
    /// including its DISTINCT flag.
    ///
    /// Prefer this over `agg_func_type`, which sees only the name. Four sites
    /// derived the type independently and two of them forgot to OR in
    /// AGG_DISTINCT, so DISTINCT was silently dropped from every aggregate in
    /// a grouped query -- and HAVING, which did set the flag, then failed to
    /// match the aggregate it had been given.
    pub(crate) fn agg_func_type_for(func: &Function) -> i64 {
        let name = func.name.to_string().to_uppercase();
        Self::agg_func_type(&name)
            | if func_is_distinct(func) {
                AGG_DISTINCT
            } else {
                0
            }
    }

    /// Convert aggregate function name to type code
    pub(crate) fn agg_func_type(name: &str) -> i64 {
        match name {
            "COUNT" => AGG_COUNT,
            "SUM" => AGG_SUM,
            "AVG" => AGG_AVG,
            "MIN" => AGG_MIN,
            "MAX" => AGG_MAX,
            _ => AGG_COUNT, // Default to COUNT
        }
    }

    /// Patch a jump instruction's target address (p2)
    pub(crate) fn patch_jump(&mut self, addr: usize, target: usize) {
        if let Some(inst) = self.program.instructions.get_mut(addr) {
            inst.p2 = target as i64;
        }
    }

    /// Convert SQL type to internal type string
    pub(crate) fn sql_type_to_internal(data_type: &str) -> &'static str {
        match data_type.to_uppercase().as_str() {
            "INTEGER" | "INT" => "INTEGER",
            "REAL" | "FLOAT" | "DOUBLE" => "REAL",
            "BOOLEAN" | "BOOL" => "BOOLEAN",
            _ => "TEXT",
        }
    }

    // Removed unused add_halt method

    /// Add a comment to the program if verbose mode is enabled
    pub(crate) fn add_comment(&mut self, comment: &str) {
        if self.verbose {
            self.emit(OpCode::Noop, 0, 0, 0, None, comment);
        }
    }

    // Method compile_query_direct removed - will be reimplemented when we update to a newer sqlparser version
    // TODO: Add direct query compilation support

    /// Compile an SQL string into bytecode
    /// Compile a single already-parsed statement into its own program.
    ///
    /// Each statement gets its own program so it can be executed, and its
    /// modifications applied, before the next one is compiled -- which is what
    /// lets a later statement see an earlier one's effects.
    pub fn compile_statement_program(&mut self, statement: &Statement) -> SqawkResult<Program> {
        self.program = Program::new();
        self.reset_registers();
        self.table_map.clear();
        self.label_addrs.clear();
        self.pending_jumps.clear();
        self.pending_jumps_three.clear();

        let init_addr = self.program.len();
        self.emit(OpCode::Init, 0, 0, 0, None, "Start address filled in later");

        self.compile_statement(statement)?;

        self.emit(OpCode::Halt, 0, 0, 0, None, "End execution");

        let start = init_addr + 1;
        if let Some(instruction) = self.program.instructions.get_mut(init_addr) {
            instruction.p2 = start as i64;
            instruction.comment = Some(format!("Start at {}", start).into());
        }

        self.finish_labels()?;
        self.program.register_count = self.register_counter;
        Ok(self.program.clone())
    }

    /// Parse and compile `sql` into a single program.
    ///
    /// Convenience wrapper used by the compiler unit tests, which examine
    /// generated bytecode for one statement. Execution goes through
    /// `compile_statement_program` per statement instead, so that each
    /// statement can observe the previous one's effects.
    #[allow(dead_code)]
    pub fn compile(&mut self, sql: &str) -> SqawkResult<Program> {
        // Reset state for new compilation
        self.program = Program::new();
        self.reset_registers();
        self.table_map.clear();
        self.label_addrs.clear();
        self.pending_jumps.clear();
        self.pending_jumps_three.clear();

        // Parse the SQL statement
        let dialect = HiveDialect {};
        let statements = Parser::parse_sql(&dialect, sql).map_err(SqawkError::SqlParseError)?;

        if statements.is_empty() {
            return Err(SqawkError::InvalidSqlQuery(
                "No SQL statements found".to_string(),
            ));
        }

        // Add initial "Init" instruction that will be filled in later
        // with the address of the main program body
        let init_addr = self.program.len();
        self.emit(
            OpCode::Init,
            0,
            0,
            0,
            None,
            "Start address will be filled in later",
        );

        // Compile each statement
        for statement in statements {
            self.compile_statement(&statement)?;
        }

        // Add Halt instruction at the end
        self.emit(OpCode::Halt, 0, 0, 0, None, "End execution");

        // Go back and update the Init instruction with the correct start address
        // (usually this would point to setup code like transaction start)
        let transaction_addr = init_addr + 1;
        if let Some(instruction) = self.program.instructions.get_mut(init_addr) {
            instruction.p2 = transaction_addr as i64;
            instruction.comment = Some(format!("Start at {}", transaction_addr).into());
        }

        // Patch every symbolic jump now that all addresses are known. This
        // errors rather than emitting a program with a placeholder target.
        self.finish_labels()?;

        // Hand the engine the real register high-water mark.
        self.program.register_count = self.register_counter;

        Ok(self.program.clone())
    }

    // Removed unused compile_statement_into_program method

    /// Compile a single SQL statement
    fn compile_statement(&mut self, statement: &Statement) -> SqawkResult<()> {
        match statement {
            Statement::Query(query) => self.compile_query(query),
            Statement::Insert(insert) => {
                let source = insert.source.as_ref().ok_or_else(|| {
                    SqawkError::UnsupportedSqlFeature("INSERT without a source".into())
                })?;
                // `Insert::columns` became Vec<ObjectName>; sqawk only accepts
                // bare column names, so flatten each to its last segment.
                let columns: Vec<Ident> = insert
                    .columns
                    .iter()
                    .map(|c| Ident::new(object_name_last(c)))
                    .collect();
                self.compile_insert(insert_target(&insert.table)?, &columns, source)
            }
            Statement::Delete(delete) => {
                self.compile_delete(delete_from(&delete.from), delete.selection.as_ref())
            }
            Statement::Update(update) => self.compile_update(
                &update.table,
                &update.assignments,
                update.selection.as_ref(),
            ),
            Statement::CreateTable(create) => {
                if let Some(q) = &create.query {
                    // CREATE TABLE ... AS SELECT
                    self.compile_create_table_as_select(&create.name, q)
                } else {
                    self.compile_create_table(
                        &create.name,
                        &create.columns,
                        &create.hive_formats,
                        &create.location,
                        create_table_options(&create.table_options),
                    )
                }
            }
            Statement::Drop {
                object_type,
                names,
                if_exists,
                ..
            } => self.compile_drop(object_type, names, *if_exists),
            Statement::AlterTable(alter) => {
                // `operation` became `operations`; sqawk handles one at a time.
                match alter.operations.as_slice() {
                    [operation] => self.compile_alter_table(&alter.name, operation),
                    _ => Err(SqawkError::UnsupportedSqlFeature(
                        "ALTER TABLE with multiple operations is not supported".into(),
                    )),
                }
            }
            Statement::Truncate(truncate) => match truncate.table_names.as_slice() {
                [target] => self.compile_truncate(&target.name),
                _ => Err(SqawkError::UnsupportedSqlFeature(
                    "TRUNCATE of multiple tables is not supported".into(),
                )),
            },
            _ => Err(SqawkError::UnsupportedSqlFeature(format!(
                "Unsupported SQL statement type: {:?}",
                statement
            ))),
        }
    }

    /// Compile a SQL query
    fn compile_query(&mut self, query: &Query) -> SqawkResult<()> {
        // `ORDER BY ALL` carries no key list, so it would otherwise look
        // identical to "no ORDER BY" and be silently ignored. Reject it.
        if is_order_by_all(query) {
            return Err(SqawkError::UnsupportedSqlFeature(
                "ORDER BY ALL is not supported".into(),
            ));
        }

        match &*query.body {
            SetExpr::Select(select) => self.compile_select(select, Some(query))?,
            SetExpr::SetOperation {
                op,
                left,
                right,
                set_quantifier,
                ..
            } => {
                let all = *set_quantifier == SetQuantifier::All;
                self.compile_set_operation(op, left, right, all)?;
                // TODO: Handle ORDER BY/LIMIT for set operations
            }
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT statements are supported".to_string(),
                ));
            }
        }

        Ok(())
    }

    /// Compile a set operation (UNION, INTERSECT, EXCEPT)
    fn compile_set_operation(
        &mut self,
        op: &SetOperator,
        left: &SetExpr,
        right: &SetExpr,
        all: bool,
    ) -> SqawkResult<()> {
        self.add_comment(&format!(
            "Set operation: {:?}{}",
            op,
            if all { " ALL" } else { "" }
        ));

        // For INTERSECT and EXCEPT, we need to track where the left results end
        let left_results_marker = match op {
            SetOperator::Intersect | SetOperator::Except => {
                // Use a register to store the count of left-side results
                let marker_reg = self.allocate_register();
                Some(marker_reg)
            }
            _ => None,
        };

        // Compile the left side
        self.compile_set_expr(left)?;

        // For INTERSECT and EXCEPT, record the boundary
        if let Some(marker_reg) = left_results_marker {
            // Add a marker instruction that the VM will use to know where left results end
            // p1=-1 is a special value meaning "use current result count"
            // p2 is the destination register
            self.emit(
                OpCode::Integer,
                -1, // Special marker: -1 means "current result count"
                marker_reg,
                0,
                None,
                "Store current result count",
            );
        }

        // Compile the right side
        self.compile_set_expr(right)?;

        // Add the appropriate set operation opcode
        match op {
            SetOperator::Union => {
                if !all {
                    // UNION (without ALL) needs to remove duplicates
                    self.emit(
                        OpCode::Distinct,
                        0,
                        0,
                        0,
                        None,
                        "Remove duplicate rows for UNION",
                    );
                }
                // UNION ALL: no additional processing needed, results are already combined
            }
            SetOperator::Intersect => {
                self.emit(
                    OpCode::Intersect,
                    left_results_marker.unwrap_or(0),
                    0,
                    0,
                    None,
                    "Keep only rows in both result sets",
                );
            }
            SetOperator::Except | SetOperator::Minus => {
                self.emit(
                    OpCode::Except,
                    left_results_marker.unwrap_or(0),
                    0,
                    0,
                    None,
                    "Keep only rows in left but not in right",
                );
            }
        }

        Ok(())
    }

    /// Compile a set expression (can be a SELECT or nested set operation)
    fn compile_set_expr(&mut self, expr: &SetExpr) -> SqawkResult<()> {
        match expr {
            SetExpr::Select(select) => self.compile_select(select, None),
            SetExpr::SetOperation {
                op,
                left,
                right,
                set_quantifier,
                ..
            } => {
                let all = *set_quantifier == SetQuantifier::All;
                self.compile_set_operation(op, left, right, all)
            }
            _ => Err(SqawkError::UnsupportedSqlFeature(
                "Unsupported set expression type".to_string(),
            )),
        }
    }

    /// Compile a SELECT.
    ///
    /// `query` carries ORDER BY / LIMIT / OFFSET when the SELECT is a query's
    /// whole body; a set-operation operand passes `None`.
    ///
    /// Every FROM shape -- one table, a comma list, any chain of joins -- goes
    /// through the one FROM planner, and the stage after it (plain
    /// projection, aggregation, windows) consumes rows from the planner's loop
    /// nest without knowing how many tables produced them.
    fn compile_select(&mut self, select: &Select, query: Option<&Query>) -> SqawkResult<()> {
        // `GROUP BY ALL` carries no key list, so it would otherwise look
        // identical to "no GROUP BY" and silently collapse the query. Reject it.
        if is_group_by_all(&select.group_by) {
            return Err(SqawkError::UnsupportedSqlFeature(
                "GROUP BY ALL is not supported".into(),
            ));
        }

        if select.from.is_empty() {
            self.compile_select_literal(select)?;
            if select.distinct.is_some() {
                self.emit(OpCode::Distinct, 0, 0, 0, None, "Remove duplicate rows");
            }
            return Ok(());
        }

        let plan = self.plan_from(&select.from, select.selection.as_ref())?;

        // Correlated-subquery detection matches qualifiers against the outer
        // table's alias.
        self.current_outer_alias = match (&select.from[0].relation, plan.srcs.len()) {
            (sqlparser::ast::TableFactor::Table { alias: Some(a), .. }, 1) => {
                Some(a.name.value.clone())
            }
            _ => None,
        };

        let has_group_by = !group_by_exprs(&select.group_by).is_empty();
        let has_aggregates = self.has_aggregates(&select.projection) || select.having.is_some();

        if self.has_window_functions(&select.projection) {
            let (table, table_name) = plan.single_table().ok_or_else(|| {
                SqawkError::UnsupportedSqlFeature(
                    "Window functions over a join are not supported".into(),
                )
            })?;
            let table_name = table_name.to_string();
            self.compile_select_with_window(select, table, &table_name)?;
        } else if has_group_by || has_aggregates {
            self.compile_select_grouped(select, &plan)?;
        } else {
            return self.compile_select_plain(select, query, &plan);
        }

        // These stages emit finished rows, so DISTINCT, ORDER BY and LIMIT
        // are applied to the result set.
        if select.distinct.is_some() {
            self.emit(OpCode::Distinct, 0, 0, 0, None, "Remove duplicate rows");
        }
        if let Some(query) = query {
            self.emit_result_post_processing(select, query)?;
        }
        Ok(())
    }

    /// A SELECT without aggregation or window functions: the projection is
    /// computed per row inside the loop nest, then sorted (ORDER BY) or
    /// emitted directly, with OFFSET/LIMIT counted on output rows.
    fn compile_select_plain(
        &mut self,
        select: &Select,
        query: Option<&Query>,
        plan: &FromPlan<'a>,
    ) -> SqawkResult<()> {
        let outs = self.expand_projection(&select.projection, plan)?;
        let ctx = plan.ctx();
        let mut schema = ResultSchema::new();
        for out in &outs {
            schema.add_column(out.name.clone(), self.infer_expr_type(&out.expr, &ctx));
        }
        self.program.set_result_schema(schema);

        let n = outs.len();
        let order_by: &[OrderByExpr] = query.map(query_order_by).unwrap_or(&[]);
        let (limit, offset) = match query {
            Some(q) => self.extract_limit_offset(q)?,
            None => (None, 0),
        };
        // With DISTINCT the row count is known only after deduplication, so
        // LIMIT/OFFSET are applied to the finished result instead of inline.
        let distinct = select.distinct.is_some();
        let exit = self.label();

        if order_by.is_empty() {
            let out_regs = self.allocate_registers(n.max(1));
            let counters = if distinct {
                (None, None)
            } else {
                self.emit_limit_counters(limit, offset, exit)
            };
            self.emit_scan(plan, &mut |c, ctx| {
                for (i, out) in outs.iter().enumerate() {
                    c.code_expr(&out.expr, ctx, Some(out_regs + i as i64))?;
                }
                c.emit_limited_result_row(out_regs, n, counters, exit);
                Ok(())
            })?;
        } else {
            // Sorter payload is [sort keys.., output columns..]: a key is just
            // another value computed per row, projected or not.
            enum Key<'e> {
                /// An output column: `ORDER BY 2` or `ORDER BY alias`.
                Out(usize),
                Expr(&'e Expr),
            }
            let mut keys = Vec::with_capacity(order_by.len());
            for ob in order_by {
                let key = if let Some(i) = Self::order_by_ordinal(&ob.expr, n)? {
                    Key::Out(i)
                } else if let Some(i) = Self::alias_position(&outs, &ob.expr) {
                    Key::Out(i)
                } else if let Some(i) = Self::bare_output_position(&outs, &ob.expr, &ctx) {
                    Key::Out(i)
                } else {
                    Key::Expr(&ob.expr)
                };
                keys.push(key);
            }
            let nk = keys.len();
            let total = nk + n;
            let spec: String = order_by
                .iter()
                .enumerate()
                .map(|(i, ob)| {
                    format!("{}:{}", i, if order_by_is_asc(ob) { "asc" } else { "desc" })
                })
                .collect::<Vec<_>>()
                .join(",");
            let sorter_id = 0i64;
            self.emit(
                OpCode::SorterOpen,
                sorter_id,
                total as i64,
                0,
                Some(spec),
                "ORDER BY",
            );
            let row = self.allocate_registers(total);
            self.emit_scan(plan, &mut |c, ctx| {
                for (i, out) in outs.iter().enumerate() {
                    c.code_expr(&out.expr, ctx, Some(row + (nk + i) as i64))?;
                }
                for (i, key) in keys.iter().enumerate() {
                    match key {
                        Key::Out(j) => c.emit(
                            OpCode::Copy,
                            row + (nk + j) as i64,
                            row + i as i64,
                            0,
                            None,
                            "sort key = output column",
                        ),
                        Key::Expr(e) => {
                            c.code_expr(e, ctx, Some(row + i as i64))?;
                        }
                    }
                }
                c.emit(OpCode::SorterInsert, sorter_id, row, total as i64, None, "");
                Ok(())
            })?;
            self.emit_jump_to(OpCode::SorterSort, sorter_id, exit, 0, None, "empty: done");
            let counters = if distinct {
                (None, None)
            } else {
                self.emit_limit_counters(limit, offset, exit)
            };
            let top = self.label();
            self.resolve(top);
            self.emit(OpCode::SorterData, sorter_id, row, total as i64, None, "");
            self.emit_limited_result_row(row + nk as i64, n, counters, exit);
            self.emit_jump_to(OpCode::SorterNext, sorter_id, top, 0, None, "");
        }
        self.resolve(exit);

        if distinct {
            self.emit(OpCode::Distinct, 0, 0, 0, None, "Remove duplicate rows");
            if limit.is_some() || offset > 0 {
                self.emit(
                    OpCode::Limit,
                    limit.unwrap_or(i64::MAX),
                    offset,
                    0,
                    None,
                    "LIMIT after DISTINCT",
                );
            }
        }
        Ok(())
    }

    /// Initialize LIMIT / OFFSET counters: (limit register, offset register).
    ///
    /// `LIMIT 0` jumps straight to `exit`.
    fn emit_limit_counters(
        &mut self,
        limit: Option<i64>,
        offset: i64,
        exit: Label,
    ) -> (Option<i64>, Option<i64>) {
        if limit == Some(0) {
            self.emit_jump_to(OpCode::Goto, 0, exit, 0, None, "LIMIT 0");
        }
        let lim = limit.map(|l| {
            let r = self.allocate_register();
            self.emit(OpCode::Integer, l, r, 0, None, "LIMIT counter");
            r
        });
        let off = (offset > 0).then(|| {
            let r = self.allocate_register();
            self.emit(OpCode::Integer, offset, r, 0, None, "OFFSET counter");
            r
        });
        (lim, off)
    }

    /// Emit `ResultRow` for `n` registers at `start`, honouring the counters
    /// from [`Self::emit_limit_counters`]: the first OFFSET rows are skipped,
    /// and the LIMIT-th emitted row jumps to `exit`.
    fn emit_limited_result_row(
        &mut self,
        start: i64,
        n: usize,
        (lim, off): (Option<i64>, Option<i64>),
        exit: Label,
    ) {
        let skip = self.label();
        if let Some(off) = off {
            let dec = self.label();
            let emit = self.label();
            self.emit_jump_to(OpCode::IfPos, off, dec, 0, None, "OFFSET remaining?");
            self.emit_jump_to(OpCode::Goto, 0, emit, 0, None, "");
            self.resolve(dec);
            self.emit_jump_to(OpCode::DecrJumpZero, off, skip, 0, None, "skip row");
            self.emit_jump_to(OpCode::Goto, 0, skip, 0, None, "");
            self.resolve(emit);
        }
        self.emit(OpCode::ResultRow, start, n as i64, 0, None, "Output row");
        if let Some(lim) = lim {
            self.emit_jump_to(OpCode::DecrJumpZero, lim, exit, 0, None, "LIMIT reached");
        }
        self.resolve(skip);
    }

    /// The output column an `ORDER BY alias` names, if `expr` is one.
    fn alias_position(outs: &[OutCol], expr: &Expr) -> Option<usize> {
        let Expr::Identifier(ident) = expr else {
            return None;
        };
        outs.iter().position(|o| {
            o.alias
                .as_deref()
                .is_some_and(|a| a.eq_ignore_ascii_case(&ident.value))
        })
    }

    /// The output column a bare `ORDER BY name` means when `name` does not
    /// resolve on its own (typically: ambiguous across joined tables) but
    /// exactly one projected column reference has that name.
    fn bare_output_position(outs: &[OutCol], expr: &Expr, ctx: &NameCtx<'_>) -> Option<usize> {
        let Expr::Identifier(ident) = expr else {
            return None;
        };
        if ctx.resolve_unqualified(&ident.value).is_ok() {
            return None;
        }
        let mut hits = outs.iter().enumerate().filter(|(_, o)| match &o.expr {
            Expr::Identifier(i) => i.value.eq_ignore_ascii_case(&ident.value),
            Expr::CompoundIdentifier(parts) => parts
                .last()
                .is_some_and(|p| p.value.eq_ignore_ascii_case(&ident.value)),
            _ => false,
        });
        match (hits.next(), hits.next()) {
            (Some((i, _)), None) => Some(i),
            _ => None,
        }
    }

    /// Expand a SELECT list into one expression per output column.
    ///
    /// `*` and `t.*` become column references, so every output column --
    /// expanded or written -- is compiled by `code_expr` alike.
    pub(crate) fn expand_projection(
        &self,
        projection: &[SelectItem],
        plan: &FromPlan<'a>,
    ) -> SqawkResult<Vec<OutCol>> {
        let multi = plan.srcs.len() > 1;
        let star_name = |refname: &str, col: &str| {
            if multi && !plan.bare_star {
                format!("{}.{}", refname, col)
            } else {
                col.to_string()
            }
        };
        let column = |refname: &str, col: &str| {
            Expr::CompoundIdentifier(vec![Ident::new(refname), Ident::new(col)])
        };
        let mut outs = Vec::new();
        for item in projection {
            match item {
                SelectItem::Wildcard(_) => {
                    for (si, src) in plan.srcs.iter().enumerate() {
                        for (ci, meta) in src.table.column_metadata().iter().enumerate() {
                            if plan.is_hidden(si, ci) {
                                continue;
                            }
                            let expr = match plan.using_at(si, ci) {
                                Some(u) => Expr::Identifier(Ident::new(u.name.clone())),
                                None => column(&src.refname, &meta.name),
                            };
                            outs.push(OutCol {
                                expr,
                                name: star_name(&src.refname, &meta.name),
                                alias: None,
                            });
                        }
                    }
                }
                SelectItem::QualifiedWildcard(kind, _) => {
                    let qualifier = match kind {
                        SelectItemQualifiedWildcardKind::ObjectName(name) => {
                            object_name_last(name).to_ascii_lowercase()
                        }
                        SelectItemQualifiedWildcardKind::Expr(_) => {
                            return Err(SqawkError::UnsupportedSqlFeature(
                                "expr.* is not supported".into(),
                            ))
                        }
                    };
                    let found = plan.srcs.iter().position(|s| {
                        s.refname == qualifier || s.table.name().eq_ignore_ascii_case(&qualifier)
                    });
                    let src = match found {
                        Some(i) => &plan.srcs[i],
                        // A single table answers to its own name whatever
                        // alias it was given.
                        None if !multi => &plan.srcs[0],
                        None => return Err(SqawkError::TableNotFound(qualifier)),
                    };
                    for meta in src.table.column_metadata() {
                        outs.push(OutCol {
                            expr: column(&src.refname, &meta.name),
                            name: star_name(&src.refname, &meta.name),
                            alias: None,
                        });
                    }
                }
                SelectItem::UnnamedExpr(expr) => outs.push(OutCol {
                    expr: expr.clone(),
                    name: self.output_name(expr, multi),
                    alias: None,
                }),
                SelectItem::ExprWithAlias { expr, alias } => outs.push(OutCol {
                    expr: expr.clone(),
                    name: alias.value.clone(),
                    alias: Some(alias.value.clone()),
                }),
                // Multiple aliases for one item (`expr AS (a, b)`) is a
                // non-standard extension sqawk does not implement.
                SelectItem::ExprWithAliases { .. } => {
                    return Err(SqawkError::UnsupportedSqlFeature(
                        "Multiple column aliases are not supported".into(),
                    ))
                }
            }
        }
        Ok(outs)
    }

    /// Header for an unaliased SELECT-list expression.
    ///
    /// In a join a qualified column keeps its qualifier (`users.name`), as
    /// join output always has; a single-table query shows the bare name.
    pub(crate) fn output_name(&self, expr: &Expr, multi: bool) -> String {
        match expr {
            Expr::CompoundIdentifier(parts) if multi => parts
                .iter()
                .map(|p| p.value.as_str())
                .collect::<Vec<_>>()
                .join("."),
            _ => self.get_column_name_from_expr(expr),
        }
    }

    /// Extract LIMIT and OFFSET values from query
    pub(crate) fn extract_limit_offset(&self, query: &Query) -> SqawkResult<(Option<i64>, i64)> {
        let limit = if let Some(limit_expr) = query_limit(query) {
            match limit_expr {
                Expr::Value(ValueWithSpan {
                    value: Value::Number(n, _),
                    ..
                }) => Some(n.parse::<i64>().map_err(|_| {
                    SqawkError::InvalidSqlQuery(format!("Invalid LIMIT value: {}", n))
                })?),
                _ => {
                    return Err(SqawkError::UnsupportedSqlFeature(
                        "Only constant LIMIT supported".into(),
                    ))
                }
            }
        } else {
            None
        };

        let offset = if let Some(offset_clause) = query_offset(query) {
            match offset_clause {
                Expr::Value(ValueWithSpan {
                    value: Value::Number(n, _),
                    ..
                }) => n.parse::<i64>().map_err(|_| {
                    SqawkError::InvalidSqlQuery(format!("Invalid OFFSET value: {}", n))
                })?,
                _ => {
                    return Err(SqawkError::UnsupportedSqlFeature(
                        "Only constant OFFSET supported".into(),
                    ))
                }
            }
        } else {
            0
        };

        Ok((limit, offset))
    }

    /// Compile a SELECT with no FROM clause (e.g., `SELECT 1, 'text'`).
    ///
    /// The expressions go through `code_expr` with an empty name scope, so
    /// everything that works with a FROM clause -- string functions, CAST,
    /// CASE, `||`, predicates -- works without one. A WHERE clause decides
    /// whether the single row is emitted.
    fn compile_select_literal(&mut self, select: &Select) -> SqawkResult<()> {
        self.add_comment("Literal value query (no table)");
        let ctx = NameCtx::empty();

        let skip = self.label();
        if let Some(where_expr) = &select.selection {
            let cond = self.code_expr(where_expr, &ctx, None)?;
            self.emit_jump_to(OpCode::IfZ, cond, skip, 0, None, "WHERE false: no row");
        }

        let start_reg = self.allocate_registers(select.projection.len());
        for (i, item) in select.projection.iter().enumerate() {
            let expr = match item {
                SelectItem::UnnamedExpr(expr) | SelectItem::ExprWithAlias { expr, .. } => expr,
                _ => {
                    return Err(SqawkError::UnsupportedSqlFeature(
                        "Only simple expressions supported in SELECT without FROM".to_string(),
                    ));
                }
            };
            self.code_expr(expr, &ctx, Some(start_reg + i as i64))?;
        }

        if !select.projection.is_empty() {
            self.emit(
                OpCode::ResultRow,
                start_reg,
                select.projection.len() as i64,
                0,
                None,
                "Output literal result row",
            );
        }
        self.resolve(skip);

        Ok(())
    }

    /// Extract the column index from an aggregate function argument
    fn extract_agg_column_index(&self, func: &Function, table: &Table) -> SqawkResult<usize> {
        // Handle COUNT(*) specially
        if !func_args(func).is_empty() {
            match &func_args(func)[0] {
                FunctionArg::Unnamed(FunctionArgExpr::Wildcard) => {
                    // COUNT(*) - use first column (doesn't matter which for count)
                    return Ok(0);
                }
                FunctionArg::Unnamed(FunctionArgExpr::Expr(Expr::Identifier(ident))) => {
                    let col_name = ident.value.to_lowercase();
                    return table
                        .column_index(&col_name)
                        .ok_or(SqawkError::ColumnNotFound(col_name));
                }
                _ => {}
            }
        }
        // Default to first column
        Ok(0)
    }

    /// Emit bytecode to load a value as a literal
    fn emit_value_literal(&mut self, reg: i64, value: &TableValue) -> SqawkResult<()> {
        match value {
            TableValue::Integer(i) => {
                self.emit(
                    OpCode::Integer,
                    *i,
                    reg,
                    0,
                    None,
                    &format!("r[{}] = {} (subquery result)", reg, i),
                );
            }
            TableValue::Float(f) => {
                // Store float as string and use String opcode, then cast
                self.emit(
                    OpCode::String,
                    0,
                    reg,
                    0,
                    Some(f.to_string()),
                    &format!("r[{}] = {} (subquery result)", reg, f),
                );
                // Cast to float
                self.emit(
                    OpCode::Cast,
                    reg,
                    reg,
                    0,
                    Some("REAL".to_string()),
                    &format!("Cast r[{}] to REAL", reg),
                );
            }
            TableValue::String(s) => {
                self.emit(
                    OpCode::String,
                    0,
                    reg,
                    0,
                    Some(s.clone().into_owned()),
                    &format!("r[{}] = '{}' (subquery result)", reg, s),
                );
            }
            TableValue::Boolean(b) => {
                self.emit(
                    OpCode::Integer,
                    if *b { 1 } else { 0 },
                    reg,
                    0,
                    None,
                    &format!("r[{}] = {} (subquery result)", reg, b),
                );
            }
            TableValue::Null => {
                self.emit(
                    OpCode::Null,
                    0,
                    reg,
                    0,
                    None,
                    &format!("r[{}] = NULL (subquery result)", reg),
                );
            }
        }
        Ok(())
    }

    /// Evaluate a scalar subquery at compile time and return the result value
    /// This is used when a subquery appears as an operand in a comparison
    fn evaluate_scalar_subquery(&self, subquery: &Query) -> SqawkResult<TableValue> {
        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported".to_string(),
                ))
            }
        };

        // Verify it's a single-table query
        if select.from.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(
                "Subquery must have a FROM clause".to_string(),
            ));
        }

        // Get the table name
        let table_name = match &select.from[0].relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table references are supported in subqueries".to_string(),
                ))
            }
        };

        // Get the table
        if !self.database.has_table(&table_name) {
            return Err(SqawkError::TableNotFound(table_name.clone()));
        }
        let table = self.database.get_table(&table_name).unwrap();

        // Filter rows if there's a WHERE clause in the subquery
        let filtered_rows: Vec<&Vec<TableValue>> = if let Some(where_expr) = &select.selection {
            table
                .rows()
                .iter()
                .filter(|row| self.evaluate_where_at_compile_time(where_expr, row, table))
                .collect()
        } else {
            table.rows().iter().collect()
        };

        // Check the projection to determine what value to compute
        if select.projection.is_empty() {
            return Err(SqawkError::InvalidSqlQuery(
                "Subquery must have a projection".to_string(),
            ));
        }

        let result_value = match &select.projection[0] {
            SelectItem::UnnamedExpr(expr) => match expr {
                Expr::Function(func) => {
                    // Handle aggregate functions (MAX, MIN, COUNT, SUM, AVG)
                    let func_name = func
                        .name
                        .0
                        .first()
                        .map(|id| {
                            id.as_ident()
                                .map(|i| i.value.to_uppercase())
                                .unwrap_or_default()
                        })
                        .unwrap_or_default();

                    // Get the aggregate function
                    let agg_func = AggregateFunction::from_name(&func_name).ok_or_else(|| {
                        SqawkError::UnsupportedSqlFeature(format!(
                            "Unsupported aggregate function in subquery: {}",
                            func_name
                        ))
                    })?;

                    // Extract the column index from the function argument
                    let col_idx = self.extract_agg_column_index(func, table)?;

                    // Collect all values from that column
                    let values: Vec<TableValue> = filtered_rows
                        .iter()
                        .map(|row| row[col_idx].clone())
                        .collect();

                    // Execute the aggregate function
                    agg_func.execute(&values)?
                }
                Expr::Identifier(ident) => {
                    // Simple column reference - get first row's value
                    let col_name = ident.value.to_lowercase();
                    let col_idx = table
                        .column_index(&col_name)
                        .ok_or(SqawkError::ColumnNotFound(col_name.clone()))?;

                    if filtered_rows.is_empty() {
                        TableValue::Null
                    } else {
                        filtered_rows[0][col_idx].clone()
                    }
                }
                _ => {
                    // Default: get first column of first row
                    if filtered_rows.is_empty() {
                        TableValue::Null
                    } else {
                        filtered_rows[0][0].clone()
                    }
                }
            },
            SelectItem::Wildcard(_) => {
                // SELECT * - just get first column of first row
                if filtered_rows.is_empty() {
                    TableValue::Null
                } else {
                    filtered_rows[0][0].clone()
                }
            }
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Unsupported projection in scalar subquery".to_string(),
                ))
            }
        };

        Ok(result_value)
    }

    /// Evaluate an EXISTS subquery at compile time and return true/false
    fn evaluate_exists_subquery(&self, subquery: &Query, negated: bool) -> SqawkResult<bool> {
        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported in EXISTS clause".to_string(),
                ))
            }
        };

        // Verify it's a single-table query
        if select.from.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(
                "EXISTS subquery must have a FROM clause".to_string(),
            ));
        }

        // Get the subquery table name
        let subquery_table_name = match &select.from[0].relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table references are supported in EXISTS subqueries".to_string(),
                ))
            }
        };

        // Get the subquery table
        if !self.database.has_table(&subquery_table_name) {
            return Err(SqawkError::TableNotFound(subquery_table_name.clone()));
        }
        let subquery_table = self.database.get_table(&subquery_table_name).unwrap();

        // Check if any rows match the subquery's WHERE clause
        let has_rows = if let Some(where_expr) = &select.selection {
            subquery_table
                .rows()
                .iter()
                .any(|row| self.evaluate_where_at_compile_time(where_expr, row, subquery_table))
        } else {
            !subquery_table.rows().is_empty()
        };

        Ok(if negated { !has_rows } else { has_rows })
    }

    /// Evaluate an IN subquery at compile time and return the list of values
    fn evaluate_in_subquery_values(&self, subquery: &Query) -> SqawkResult<Vec<TableValue>> {
        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported in IN clause".to_string(),
                ))
            }
        };

        // Verify it's a single-table query
        if select.from.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(
                "IN subquery must have a FROM clause".to_string(),
            ));
        }

        // Get the subquery table name
        let subquery_table_name = match &select.from[0].relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table references are supported in IN subqueries".to_string(),
                ))
            }
        };

        // Get the subquery table
        if !self.database.has_table(&subquery_table_name) {
            return Err(SqawkError::TableNotFound(subquery_table_name.clone()));
        }
        let subquery_table = self.database.get_table(&subquery_table_name).unwrap();

        // Filter rows if there's a WHERE clause in the subquery
        let filtered_rows: Vec<&Vec<TableValue>> = if let Some(where_expr) = &select.selection {
            subquery_table
                .rows()
                .iter()
                .filter(|row| self.evaluate_where_at_compile_time(where_expr, row, subquery_table))
                .collect()
        } else {
            subquery_table.rows().iter().collect()
        };

        // Get the column index from the subquery projection
        let col_idx = if select.projection.is_empty() {
            return Err(SqawkError::InvalidSqlQuery(
                "IN subquery must have a projection".to_string(),
            ));
        } else {
            match &select.projection[0] {
                SelectItem::UnnamedExpr(Expr::Identifier(ident)) => {
                    let col_name = ident.value.to_lowercase();
                    subquery_table
                        .column_index(&col_name)
                        .ok_or(SqawkError::ColumnNotFound(col_name))?
                }
                SelectItem::Wildcard(_) => 0,
                _ => 0, // Default to first column
            }
        };

        // Collect values from the subquery result
        let values: Vec<TableValue> = filtered_rows
            .iter()
            .map(|row| row[col_idx].clone())
            .collect();

        Ok(values)
    }

    /// Evaluate a WHERE expression at compile time for subquery filtering
    fn evaluate_where_at_compile_time(
        &self,
        expr: &Expr,
        row: &[TableValue],
        table: &Table,
    ) -> bool {
        match expr {
            Expr::BinaryOp { left, op, right } => {
                match op {
                    BinaryOperator::And => {
                        self.evaluate_where_at_compile_time(left, row, table)
                            && self.evaluate_where_at_compile_time(right, row, table)
                    }
                    BinaryOperator::Or => {
                        self.evaluate_where_at_compile_time(left, row, table)
                            || self.evaluate_where_at_compile_time(right, row, table)
                    }
                    BinaryOperator::Eq
                    | BinaryOperator::NotEq
                    | BinaryOperator::Lt
                    | BinaryOperator::LtEq
                    | BinaryOperator::Gt
                    | BinaryOperator::GtEq => {
                        let left_val = self.evaluate_expr_at_compile_time(left, row, table);
                        let right_val = self.evaluate_expr_at_compile_time(right, row, table);
                        self.compare_values(&left_val, &right_val, op)
                    }
                    _ => true, // Unknown op, assume true
                }
            }
            Expr::IsNull(inner) => {
                let val = self.evaluate_expr_at_compile_time(inner, row, table);
                matches!(val, TableValue::Null)
            }
            Expr::IsNotNull(inner) => {
                let val = self.evaluate_expr_at_compile_time(inner, row, table);
                !matches!(val, TableValue::Null)
            }
            _ => true, // Unknown expression, assume true
        }
    }

    /// Evaluate an expression at compile time to get a value
    fn evaluate_expr_at_compile_time(
        &self,
        expr: &Expr,
        row: &[TableValue],
        table: &Table,
    ) -> TableValue {
        match expr {
            Expr::Identifier(ident) => {
                let col_name = ident.value.to_lowercase();
                if let Some(idx) = table.column_index(&col_name) {
                    row[idx].clone()
                } else {
                    TableValue::Null
                }
            }
            Expr::Value(ValueWithSpan { value: val, .. }) => match val {
                Value::Number(n, _) => {
                    if let Ok(i) = n.parse::<i64>() {
                        TableValue::Integer(i)
                    } else if let Ok(f) = n.parse::<f64>() {
                        TableValue::Float(f)
                    } else {
                        TableValue::String(n.clone().into())
                    }
                }
                Value::SingleQuotedString(s) | Value::DoubleQuotedString(s) => {
                    TableValue::String(s.clone().into())
                }
                Value::Boolean(b) => TableValue::Boolean(*b),
                Value::Null => TableValue::Null,
                _ => TableValue::Null,
            },
            _ => TableValue::Null,
        }
    }

    /// Compare two values using the given operator
    fn compare_values(&self, left: &TableValue, right: &TableValue, op: &BinaryOperator) -> bool {
        match (left, right) {
            (TableValue::Integer(l), TableValue::Integer(r)) => match op {
                BinaryOperator::Eq => l == r,
                BinaryOperator::NotEq => l != r,
                BinaryOperator::Lt => l < r,
                BinaryOperator::LtEq => l <= r,
                BinaryOperator::Gt => l > r,
                BinaryOperator::GtEq => l >= r,
                _ => false,
            },
            (TableValue::Float(l), TableValue::Float(r)) => match op {
                BinaryOperator::Eq => (l - r).abs() < f64::EPSILON,
                BinaryOperator::NotEq => (l - r).abs() >= f64::EPSILON,
                BinaryOperator::Lt => l < r,
                BinaryOperator::LtEq => l <= r,
                BinaryOperator::Gt => l > r,
                BinaryOperator::GtEq => l >= r,
                _ => false,
            },
            (TableValue::Integer(l), TableValue::Float(r)) => {
                let l = *l as f64;
                match op {
                    BinaryOperator::Eq => (l - r).abs() < f64::EPSILON,
                    BinaryOperator::NotEq => (l - r).abs() >= f64::EPSILON,
                    BinaryOperator::Lt => l < *r,
                    BinaryOperator::LtEq => l <= *r,
                    BinaryOperator::Gt => l > *r,
                    BinaryOperator::GtEq => l >= *r,
                    _ => false,
                }
            }
            (TableValue::Float(l), TableValue::Integer(r)) => {
                let r = *r as f64;
                match op {
                    BinaryOperator::Eq => (l - r).abs() < f64::EPSILON,
                    BinaryOperator::NotEq => (l - r).abs() >= f64::EPSILON,
                    BinaryOperator::Lt => *l < r,
                    BinaryOperator::LtEq => *l <= r,
                    BinaryOperator::Gt => *l > r,
                    BinaryOperator::GtEq => *l >= r,
                    _ => false,
                }
            }
            (TableValue::String(l), TableValue::String(r)) => match op {
                BinaryOperator::Eq => l == r,
                BinaryOperator::NotEq => l != r,
                BinaryOperator::Lt => l < r,
                BinaryOperator::LtEq => l <= r,
                BinaryOperator::Gt => l > r,
                BinaryOperator::GtEq => l >= r,
                _ => false,
            },
            (TableValue::Boolean(l), TableValue::Boolean(r)) => match op {
                BinaryOperator::Eq => l == r,
                BinaryOperator::NotEq => l != r,
                _ => false,
            },
            // Handle string to number comparisons
            (TableValue::String(s), TableValue::Integer(i)) => {
                if let Ok(n) = s.parse::<i64>() {
                    match op {
                        BinaryOperator::Eq => n == *i,
                        BinaryOperator::NotEq => n != *i,
                        BinaryOperator::Lt => n < *i,
                        BinaryOperator::LtEq => n <= *i,
                        BinaryOperator::Gt => n > *i,
                        BinaryOperator::GtEq => n >= *i,
                        _ => false,
                    }
                } else {
                    false
                }
            }
            (TableValue::Integer(i), TableValue::String(s)) => {
                if let Ok(n) = s.parse::<i64>() {
                    match op {
                        BinaryOperator::Eq => *i == n,
                        BinaryOperator::NotEq => *i != n,
                        BinaryOperator::Lt => *i < n,
                        BinaryOperator::LtEq => *i <= n,
                        BinaryOperator::Gt => *i > n,
                        BinaryOperator::GtEq => *i >= n,
                        _ => false,
                    }
                } else {
                    false
                }
            }
            _ => false, // NULL comparisons return false
        }
    }

    // =========================================================================
    // Phase 4B: Correlated Subquery Support
    // =========================================================================

    /// Detect if a subquery references outer query columns (making it correlated)
    ///
    /// A correlated subquery contains references to columns from the outer query,
    /// like: SELECT * FROM orders o WHERE amount > (SELECT AVG(amount) FROM orders WHERE user_id = o.user_id)
    /// Here, `o.user_id` is an outer reference.
    ///
    /// The outer query's names are every FROM source in `ctx`, by refname and
    /// table name, plus the alias recorded by the table-scan path. A context
    /// with no sources (no FROM) cannot be correlated with.
    fn detect_outer_references(&self, subquery: &Query, ctx: &NameCtx<'_>) -> Vec<OuterColumnRef> {
        let mut outer_refs = Vec::new();
        if ctx.srcs.is_empty() {
            return outer_refs;
        }

        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => return outer_refs,
        };

        let mut outer_names: Vec<String> = Vec::new();
        for src in &ctx.srcs {
            outer_names.push(src.refname.clone());
            outer_names.push(src.table.name().to_ascii_lowercase());
        }
        if let Some(alias) = &self.current_outer_alias {
            outer_names.push(alias.to_ascii_lowercase());
        }

        // The subquery's own table name and alias, which shadow outer names.
        let mut inner_names: Vec<String> = Vec::new();
        if let Some(sqlparser::ast::TableFactor::Table { name, alias, .. }) =
            select.from.first().map(|f| &f.relation)
        {
            if let Some(ident) = name.0.last().and_then(|p| p.as_ident()) {
                inner_names.push(ident.value.to_lowercase());
            }
            if let Some(a) = alias {
                inner_names.push(a.name.value.to_lowercase());
            }
        }

        if let Some(where_expr) = &select.selection {
            Self::collect_outer_refs_from_expr(
                where_expr,
                &outer_names,
                &inner_names,
                &mut outer_refs,
            );
        }

        outer_refs
    }

    /// Recursively collect outer column references from an expression
    fn collect_outer_refs_from_expr(
        expr: &Expr,
        outer_names: &[String],
        inner_names: &[String],
        refs: &mut Vec<OuterColumnRef>,
    ) {
        let mut walk =
            |e: &Expr| Self::collect_outer_refs_from_expr(e, outer_names, inner_names, refs);
        match expr {
            Expr::CompoundIdentifier(parts) if parts.len() == 2 => {
                let qualifier = parts[0].value.to_lowercase();
                if outer_names.contains(&qualifier) && !inner_names.contains(&qualifier) {
                    refs.push(OuterColumnRef { qualifier });
                }
            }
            Expr::BinaryOp { left, right, .. } => {
                walk(left);
                walk(right);
            }
            Expr::Nested(inner)
            | Expr::UnaryOp { expr: inner, .. }
            | Expr::IsNull(inner)
            | Expr::IsNotNull(inner)
            | Expr::Cast { expr: inner, .. }
            | Expr::Like { expr: inner, .. }
            | Expr::ILike { expr: inner, .. } => walk(inner),
            Expr::Between {
                expr, low, high, ..
            } => {
                walk(expr);
                walk(low);
                walk(high);
            }
            Expr::InList { expr, list, .. } => {
                walk(expr);
                for item in list {
                    walk(item);
                }
            }
            Expr::Case {
                operand,
                conditions,
                else_result,
                ..
            } => {
                if let Some(op) = operand {
                    walk(op);
                }
                for branch in conditions {
                    walk(&branch.condition);
                    walk(&branch.result);
                }
                if let Some(else_r) = else_result {
                    walk(else_r);
                }
            }
            Expr::Function(func) => {
                for arg in func_args(func) {
                    if let FunctionArg::Unnamed(FunctionArgExpr::Expr(e)) = arg {
                        walk(e);
                    }
                }
            }
            // Other expression types don't contain column references
            _ => {}
        }
    }

    /// Resolve the single table a correlated subquery scans.
    fn correlated_subquery_table(
        &self,
        select: &Select,
        what: &str,
    ) -> SqawkResult<(String, &'a Table)> {
        if select.from.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(format!(
                "Correlated {} subquery must have a FROM clause",
                what
            )));
        }
        let name = match &select.from[0].relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(format!(
                    "Only simple table references are supported in correlated {}",
                    what
                )))
            }
        };
        let database: &'a Database = self.database;
        let table = database.get_table(&name)?;
        Ok((name, table))
    }

    /// Name scope for a correlated subquery's condition.
    ///
    /// The subquery's own table forms the inner scope and the enclosing
    /// query's sources the outer one, which is exactly `NameCtx`'s two-level
    /// resolution: an unqualified name binds to the subquery, and a name it
    /// does not have is looked up outward. With a single outer source, every
    /// qualifier the subquery used for it (typically an alias the outer
    /// scan does not record) resolves to it too.
    fn correlated_ctx<'t>(
        subquery_table: &'t Table,
        sub_cursor: i64,
        outer: &NameCtx<'t>,
        outer_refs: &[OuterColumnRef],
    ) -> NameCtx<'t> {
        let mut ctx = NameCtx::single(subquery_table, sub_cursor);
        ctx.outer = outer.srcs.iter().chain(&outer.outer).cloned().collect();
        if let [only] = outer.srcs.as_slice() {
            for r in outer_refs {
                if !ctx.outer.iter().any(|s| s.refname == r.qualifier) {
                    let mut alias = only.clone();
                    alias.refname = r.qualifier.clone();
                    ctx.outer.push(alias);
                }
            }
        }
        ctx
    }

    /// A cursor id for a correlated subquery's scan that no outer source uses.
    fn correlated_cursor(outer: &NameCtx<'_>) -> i64 {
        outer
            .srcs
            .iter()
            .chain(&outer.outer)
            .map(|s| s.cursor)
            .max()
            .unwrap_or(0)
            + 100
    }

    /// Compile a correlated EXISTS subquery (Phase 4B) into `result_reg`.
    ///
    /// For each outer row, iterates through the subquery table and checks
    /// if any row matches the correlated condition.
    fn compile_correlated_exists_subquery(
        &mut self,
        subquery: &Query,
        negated: bool,
        outer: &NameCtx<'_>,
        outer_refs: &[OuterColumnRef],
        result_reg: i64,
    ) -> SqawkResult<()> {
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported in correlated EXISTS".to_string(),
                ))
            }
        };
        let (subquery_table_name, subquery_table) =
            self.correlated_subquery_table(select, "EXISTS")?;
        let sub_cursor = Self::correlated_cursor(outer);

        self.emit(
            OpCode::Integer,
            0,
            result_reg,
            0,
            None,
            &format!("r[{}] = 0 (EXISTS init)", result_reg),
        );
        self.emit(
            OpCode::OpenRead,
            sub_cursor,
            0,
            0,
            Some(subquery_table_name.clone()),
            &format!("Open {} for correlated EXISTS", subquery_table_name),
        );

        let done = self.label();
        self.emit_jump_to(
            OpCode::Rewind,
            sub_cursor,
            done,
            0,
            None,
            "Rewind subquery cursor",
        );
        let loop_start = self.label();
        self.resolve(loop_start);

        let next_row = self.label();
        if let Some(where_expr) = &select.selection {
            let ctx = Self::correlated_ctx(subquery_table, sub_cursor, outer, outer_refs);
            let cmp_reg = self.code_expr(where_expr, &ctx, None)?;
            self.emit_jump_to(
                OpCode::IfZ,
                cmp_reg,
                next_row,
                0,
                None,
                "Skip if WHERE condition false",
            );
        }
        self.emit(
            OpCode::Integer,
            1,
            result_reg,
            0,
            None,
            &format!("r[{}] = 1 (EXISTS match found)", result_reg),
        );
        self.emit_jump_to(OpCode::Goto, 0, done, 0, None, "Exit early on match");
        self.resolve(next_row);
        self.emit_jump_to(
            OpCode::Next,
            sub_cursor,
            loop_start,
            0,
            None,
            "Next subquery row",
        );
        self.resolve(done);

        self.emit(
            OpCode::Close,
            sub_cursor,
            0,
            0,
            None,
            "Close subquery cursor",
        );
        if negated {
            self.emit(OpCode::Not, result_reg, result_reg, 0, None, "NOT EXISTS");
        }
        Ok(())
    }

    /// Compile a correlated scalar subquery selecting one aggregate.
    fn compile_correlated_scalar_subquery(
        &mut self,
        subquery: &Query,
        outer: &NameCtx<'_>,
        outer_refs: &[OuterColumnRef],
        result_reg: i64,
    ) -> SqawkResult<()> {
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported in correlated scalar".to_string(),
                ))
            }
        };
        let (subquery_table_name, subquery_table) =
            self.correlated_subquery_table(select, "scalar")?;

        let (agg_func_name, agg_col_idx) = match select.projection.first() {
            Some(SelectItem::UnnamedExpr(Expr::Function(func))) => {
                let func_name = func.name.to_string().to_uppercase();
                let col_idx = self.extract_agg_column_index(func, subquery_table)?;
                (func_name, col_idx)
            }
            Some(_) => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Correlated scalar subquery must select an aggregate function".to_string(),
                ))
            }
            None => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Correlated scalar subquery must have a SELECT expression".to_string(),
                ))
            }
        };
        match agg_func_name.as_str() {
            "COUNT" | "SUM" | "AVG" | "MIN" | "MAX" => {}
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(format!(
                    "Unsupported aggregate in correlated subquery: {}",
                    agg_func_name
                )))
            }
        }
        let agg_type = Self::agg_func_type(agg_func_name.as_str());

        let sub_cursor = Self::correlated_cursor(outer);
        let acc_reg = self.allocate_register();
        let val_reg = self.allocate_register();

        // Initialize accumulator with Null (like SQLite does)
        // AggStep/AggFinal will treat Null as "no data yet"
        self.emit(
            OpCode::Null,
            0,
            acc_reg,
            acc_reg,
            None,
            &format!("r[{}]=NULL; Init {} accumulator", acc_reg, agg_func_name),
        );
        self.emit(
            OpCode::OpenRead,
            sub_cursor,
            0,
            0,
            Some(subquery_table_name.clone()),
            &format!("Open {} for correlated scalar", subquery_table_name),
        );

        let done = self.label();
        self.emit_jump_to(
            OpCode::Rewind,
            sub_cursor,
            done,
            0,
            None,
            "Rewind subquery cursor",
        );
        let loop_start = self.label();
        self.resolve(loop_start);

        let next_row = self.label();
        if let Some(where_expr) = &select.selection {
            let ctx = Self::correlated_ctx(subquery_table, sub_cursor, outer, outer_refs);
            let cmp_reg = self.code_expr(where_expr, &ctx, None)?;
            self.emit_jump_to(
                OpCode::IfZ,
                cmp_reg,
                next_row,
                0,
                None,
                "Skip if WHERE false",
            );
        }
        self.emit(
            OpCode::Column,
            sub_cursor,
            agg_col_idx as i64,
            val_reg,
            None,
            &format!("r[{}] = subquery column for agg", val_reg),
        );
        self.emit(
            OpCode::AggStep,
            agg_type,
            val_reg,
            acc_reg,
            None,
            &format!(
                "Aggregate step: {} r[{}] -> r[{}]",
                agg_func_name, val_reg, acc_reg
            ),
        );
        self.resolve(next_row);
        self.emit_jump_to(
            OpCode::Next,
            sub_cursor,
            loop_start,
            0,
            None,
            "Next subquery row",
        );
        self.resolve(done);

        // P3 = function type hint for when no AggStep was called (register still Null)
        self.emit(
            OpCode::AggFinal,
            acc_reg,
            result_reg,
            agg_type,
            None,
            &format!("r[{}] = final {} result", result_reg, agg_func_name),
        );
        self.emit(
            OpCode::Close,
            sub_cursor,
            0,
            0,
            None,
            "Close subquery cursor",
        );
        Ok(())
    }

    /// Compile `expr [NOT] LIKE pattern` (or ILIKE) into `dest`.
    ///
    /// A NULL operand yields NULL for both LIKE and NOT LIKE.
    fn compile_like_pattern(
        &mut self,
        expr: &Expr,
        pattern: &Expr,
        negated: bool,
        case_insensitive: bool,
        ctx: &NameCtx<'_>,
        dest: i64,
    ) -> SqawkResult<()> {
        let pattern_str = match pattern {
            Expr::Value(ValueWithSpan {
                value: Value::SingleQuotedString(s),
                ..
            }) => s.clone(),
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "LIKE pattern must be a string literal".to_string(),
                ))
            }
        };
        let value_reg = self.code_expr(expr, ctx, None)?;

        // P2 encodes: bit 0 = negated, bit 1 = case_insensitive
        let flags = (negated as i64) | ((case_insensitive as i64) << 1);
        self.emit(
            OpCode::Like,
            value_reg,
            flags,
            dest,
            Some(pattern_str.clone()),
            &format!(
                "r[{}] = r[{}] {}LIKE '{}'",
                dest,
                value_reg,
                if negated { "NOT " } else { "" },
                pattern_str
            ),
        );
        Ok(())
    }

    /// Compile `expr [NOT] BETWEEN low AND high` into `dest`.
    ///
    /// Exactly `expr >= low AND expr <= high` under three-valued logic, so a
    /// NULL anywhere gives NULL unless the other bound already decides false.
    fn compile_between(
        &mut self,
        expr: &Expr,
        low: &Expr,
        high: &Expr,
        negated: bool,
        ctx: &NameCtx<'_>,
        dest: i64,
    ) -> SqawkResult<()> {
        let x = self.code_expr(expr, ctx, None)?;
        let lo = self.code_expr(low, ctx, None)?;
        let hi = self.code_expr(high, ctx, None)?;
        let ge = self.allocate_register();
        let le = self.allocate_register();
        self.emit(
            OpCode::Ge,
            x,
            lo,
            ge,
            None,
            &format!("r[{}] = r[{}] >= r[{}]", ge, x, lo),
        );
        self.emit(
            OpCode::Le,
            x,
            hi,
            le,
            None,
            &format!("r[{}] = r[{}] <= r[{}]", le, x, hi),
        );
        self.emit(OpCode::And, ge, le, dest, None, "BETWEEN");
        if negated {
            self.emit(OpCode::Not, dest, dest, 0, None, "NOT BETWEEN");
        }
        Ok(())
    }

    /// Compile `expr [NOT] IN (list)` into `dest` (see [`Self::emit_in_step`]).
    fn compile_in_list(
        &mut self,
        expr: &Expr,
        list: &[Expr],
        negated: bool,
        ctx: &NameCtx<'_>,
        dest: i64,
    ) -> SqawkResult<()> {
        if list.is_empty() {
            self.emit_empty_in(negated, dest);
            return Ok(());
        }
        let x = self.code_expr(expr, ctx, None)?;
        let item = self.allocate_register();
        let hit = self.allocate_register();
        self.emit(OpCode::Integer, 0, dest, 0, None, "IN list init");
        for value in list {
            self.code_expr(value, ctx, Some(item))?;
            self.emit_in_step(x, item, hit, dest);
        }
        if negated {
            self.emit(OpCode::Not, dest, dest, 0, None, "NOT IN");
        }
        Ok(())
    }

    /// Compile a SUBSTRING/SUBSTR expression into `target_reg`.
    ///
    /// `SUBSTR(x, 1, 3)` and `SUBSTRING(x FROM 1 FOR 3)` are the same
    /// `Expr::Substring` node.
    fn compile_substring(
        &mut self,
        sub_expr: &Expr,
        substring_from: Option<&Expr>,
        substring_for: Option<&Expr>,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        // A start position is required.
        //
        // sqlparser 0.62 parses `SUBSTR(x)` into this node with no start, and
        // defaulting it to 1 returned the whole string unchanged -- so a
        // dropped or mistyped argument silently produced untruncated output.
        let Some(from_expr) = substring_from else {
            return Err(SqawkError::InvalidSqlQuery(
                "SUBSTR requires at least two arguments".to_string(),
            ));
        };

        let src_reg = self.code_expr(sub_expr, ctx, None)?;
        let start_reg = self.code_expr(from_expr, ctx, None)?;

        // A length, if given, is passed to the engine via the P4 spec.
        let func_spec = if let Some(for_expr) = substring_for {
            let len_reg = self.code_expr(for_expr, ctx, None)?;
            format!("SUBSTR:{}", len_reg)
        } else {
            "SUBSTR".to_string()
        };

        self.emit(
            OpCode::StringFunc,
            src_reg,
            target_reg,
            start_reg,
            Some(func_spec),
            &format!("r[{}] = SUBSTR(...)", target_reg),
        );
        Ok(())
    }

    /// Compile a CASE expression into `dest`.
    ///
    /// Supports both:
    /// - Simple CASE: CASE expr WHEN val1 THEN res1 ... ELSE default END
    /// - Searched CASE: CASE WHEN cond1 THEN res1 ... ELSE default END
    ///
    /// A WHEN whose test is NULL (UNKNOWN) does not match, in both forms.
    fn compile_case(
        &mut self,
        operand: Option<&Expr>,
        conditions: &[CaseWhen],
        else_result: Option<&Expr>,
        ctx: &NameCtx<'_>,
        dest: i64,
    ) -> SqawkResult<()> {
        // For simple CASE, compile the operand once.
        let operand_reg = match operand {
            Some(op_expr) => Some(self.code_expr(op_expr, ctx, None)?),
            None => None,
        };
        let end = self.label();

        for CaseWhen { condition, result } in conditions {
            let test_reg = match operand_reg {
                Some(op_reg) => {
                    let val_reg = self.code_expr(condition, ctx, None)?;
                    let eq_reg = self.allocate_register();
                    self.emit(
                        OpCode::Eq,
                        op_reg,
                        val_reg,
                        eq_reg,
                        None,
                        &format!("r[{}] = (r[{}] == r[{}]) for CASE", eq_reg, op_reg, val_reg),
                    );
                    eq_reg
                }
                None => self.code_expr(condition, ctx, None)?,
            };
            let next = self.label();
            self.emit_jump_to(
                OpCode::IfZ,
                test_reg,
                next,
                0,
                None,
                "if WHEN condition false, try next",
            );
            self.code_expr(result, ctx, Some(dest))?;
            self.emit_jump_to(OpCode::Goto, 0, end, 0, None, "jump to CASE end");
            self.resolve(next);
        }

        match else_result {
            Some(else_expr) => {
                self.code_expr(else_expr, ctx, Some(dest))?;
            }
            None => self.emit(
                OpCode::Null,
                0,
                dest,
                0,
                None,
                &format!("r[{}] = NULL (no ELSE in CASE)", dest),
            ),
        }
        self.resolve(end);
        Ok(())
    }

    /// Extract function name from a Function AST node
    fn get_function_name(func: &Function) -> String {
        func.name
            .0
            .iter()
            .map(|id| id.as_ident().map(|i| i.value.as_str()).unwrap_or_default())
            .collect::<Vec<_>>()
            .join(".")
            .to_uppercase()
    }

    /// Compile COALESCE function - returns first non-NULL argument
    fn compile_func_coalesce(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).is_empty() {
            return Err(SqawkError::InvalidSqlQuery(
                "COALESCE requires at least one argument".to_string(),
            ));
        }

        let mut jump_to_end_addrs = Vec::new();

        for arg in func_args(func) {
            let expr = self.extract_function_arg_expr(arg)?;
            let arg_reg = self.allocate_register();
            let null_check_reg = self.allocate_register();

            // Compile the argument
            self.code_expr_into(&expr, ctx, arg_reg)?;

            // Check if it's NULL
            self.emit(
                OpCode::IsNull,
                arg_reg,
                null_check_reg,
                0,
                None,
                &format!("r[{}] = (r[{}] IS NULL)", null_check_reg, arg_reg),
            );

            // If NULL (null_check_reg == 1), skip to next argument
            let skip_addr = self.program.len();
            self.emit(
                OpCode::IfZ,
                null_check_reg,
                0, // Will be patched to "use this value"
                0,
                None,
                "if NOT NULL, use this value",
            );

            // Patch to jump to next iteration (will be set at end of this iteration)
            let continue_to_next = self.program.len();

            // Add a goto to skip to next arg check (this arg was NULL)
            self.emit(
                OpCode::Goto,
                0,
                0, // Will be patched to next arg check
                0,
                None,
                "skip to next arg (this was NULL)",
            );

            // Patch the IfZ to come here when not NULL
            let use_value_addr = self.program.len();
            if let Some(inst) = self.program.instructions.get_mut(skip_addr) {
                inst.p2 = use_value_addr as i64;
            }

            // Copy value to target register (value is not NULL)
            // Cast to same type as workaround for copy
            self.emit(
                OpCode::Cast,
                arg_reg,
                target_reg,
                0,
                Some("TEXT".to_string()),
                &format!("r[{}] = r[{}] (COALESCE result)", target_reg, arg_reg),
            );

            // Jump to end (we found a non-NULL value)
            jump_to_end_addrs.push(self.program.len());
            self.emit(
                OpCode::Goto,
                0,
                0, // Will be patched to end
                0,
                None,
                "jump to COALESCE end",
            );

            // Patch the continue_to_next goto to jump here
            let next_arg_addr = self.program.len();
            if let Some(inst) = self.program.instructions.get_mut(continue_to_next) {
                inst.p2 = next_arg_addr as i64;
            }
        }

        // If all args were NULL, result is NULL
        self.emit(
            OpCode::Null,
            0,
            target_reg,
            0,
            None,
            &format!("r[{}] = NULL (all COALESCE args were NULL)", target_reg),
        );

        // Patch all jump-to-end addresses
        let end_label = self.program.len();
        for addr in jump_to_end_addrs {
            if let Some(inst) = self.program.instructions.get_mut(addr) {
                inst.p2 = end_label as i64;
            }
        }

        Ok(())
    }

    /// Compile NULLIF function - returns NULL if both args are equal
    fn compile_func_nullif(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).len() != 2 {
            return Err(SqawkError::InvalidSqlQuery(
                "NULLIF requires exactly two arguments".to_string(),
            ));
        }

        let expr1 = self.extract_function_arg_expr(&func_args(func)[0])?;
        let expr2 = self.extract_function_arg_expr(&func_args(func)[1])?;

        let reg1 = self.allocate_register();
        let reg2 = self.allocate_register();
        let cmp_reg = self.allocate_register();

        // Compile both arguments
        self.code_expr_into(&expr1, ctx, reg1)?;
        self.code_expr_into(&expr2, ctx, reg2)?;

        // Compare them
        self.emit(
            OpCode::Eq,
            reg1,
            reg2,
            cmp_reg,
            None,
            &format!("r[{}] = (r[{}] == r[{}])", cmp_reg, reg1, reg2),
        );

        // If equal (cmp_reg == 1), return NULL; else return reg1
        let not_equal_addr = self.program.len();
        self.emit(
            OpCode::IfZ,
            cmp_reg,
            0, // Will be patched
            0,
            None,
            "if NOT equal, jump",
        );

        // Values are equal, set result to NULL
        self.emit(
            OpCode::Null,
            0,
            target_reg,
            0,
            None,
            &format!("r[{}] = NULL (values equal)", target_reg),
        );

        let skip_else_addr = self.program.len();
        self.emit(
            OpCode::Goto,
            0,
            0, // Will be patched
            0,
            None,
            "skip else branch",
        );

        // Patch IfZ to jump here (values not equal)
        let else_addr = self.program.len();
        if let Some(inst) = self.program.instructions.get_mut(not_equal_addr) {
            inst.p2 = else_addr as i64;
        }

        // Values not equal, copy reg1 to target
        self.emit(
            OpCode::Cast,
            reg1,
            target_reg,
            0,
            Some("TEXT".to_string()),
            &format!("r[{}] = r[{}] (values not equal)", target_reg, reg1),
        );

        // Patch skip_else to jump here
        let end_addr = self.program.len();
        if let Some(inst) = self.program.instructions.get_mut(skip_else_addr) {
            inst.p2 = end_addr as i64;
        }

        Ok(())
    }

    /// Compile simple string functions (UPPER, LOWER, TRIM, LTRIM, RTRIM, LENGTH)
    fn compile_func_string_simple(
        &mut self,
        func_name: &str,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).is_empty() {
            return Err(SqawkError::InvalidSqlQuery(format!(
                "{} requires one argument",
                func_name
            )));
        }

        let expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let src_reg = self.allocate_register();

        // Compile the argument
        self.code_expr_into(&expr, ctx, src_reg)?;

        // Emit StringFunc opcode
        self.emit(
            OpCode::StringFunc,
            src_reg,
            target_reg,
            0,
            Some(func_name.to_string()),
            &format!("r[{}] = {}(r[{}])", target_reg, func_name, src_reg),
        );

        Ok(())
    }

    /// Compile SUBSTR/SUBSTRING function
    fn compile_func_substr(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).len() < 2 {
            return Err(SqawkError::InvalidSqlQuery(
                "SUBSTR requires at least two arguments".to_string(),
            ));
        }

        let str_expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let start_expr = self.extract_function_arg_expr(&func_args(func)[1])?;

        let str_reg = self.allocate_register();
        let start_reg = self.allocate_register();

        // Compile string and start arguments
        self.code_expr_into(&str_expr, ctx, str_reg)?;
        self.code_expr_into(&start_expr, ctx, start_reg)?;

        // Check if we have a length argument
        let func_spec = if func_args(func).len() >= 3 {
            let len_expr = self.extract_function_arg_expr(&func_args(func)[2])?;
            let len_reg = self.allocate_register();
            self.code_expr_into(&len_expr, ctx, len_reg)?;
            format!("SUBSTR:{}", len_reg)
        } else {
            "SUBSTR".to_string()
        };

        // Emit StringFunc opcode
        self.emit(
            OpCode::StringFunc,
            str_reg,
            target_reg,
            start_reg,
            Some(func_spec),
            &format!("r[{}] = SUBSTR(...)", target_reg),
        );

        Ok(())
    }

    /// Compile REPLACE function
    fn compile_func_replace(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).len() != 3 {
            return Err(SqawkError::InvalidSqlQuery(
                "REPLACE requires three arguments".to_string(),
            ));
        }

        let str_expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let from_expr = self.extract_function_arg_expr(&func_args(func)[1])?;
        let to_expr = self.extract_function_arg_expr(&func_args(func)[2])?;

        let str_reg = self.allocate_register();
        let from_reg = self.allocate_register();
        let to_reg = self.allocate_register();

        // Compile all three arguments
        self.code_expr_into(&str_expr, ctx, str_reg)?;
        self.code_expr_into(&from_expr, ctx, from_reg)?;
        self.code_expr_into(&to_expr, ctx, to_reg)?;

        // Emit StringFunc opcode with from_reg and to_reg in P4
        self.emit(
            OpCode::StringFunc,
            str_reg,
            target_reg,
            0,
            Some(format!("REPLACE:{}:{}", from_reg, to_reg)),
            &format!("r[{}] = REPLACE(...)", target_reg),
        );

        Ok(())
    }

    /// Compile CONCAT function
    fn compile_func_concat(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).len() < 2 {
            return Err(SqawkError::InvalidSqlQuery(
                "CONCAT requires at least two arguments".to_string(),
            ));
        }

        // Compile first argument to src_reg
        let first_expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let src_reg = self.allocate_register();
        self.code_expr_into(&first_expr, ctx, src_reg)?;

        // Compile remaining arguments and build P4 spec
        let mut arg_regs = Vec::with_capacity(func_args(func).len().saturating_sub(1));
        for arg in func_args(func).iter().skip(1) {
            let expr = self.extract_function_arg_expr(arg)?;
            let reg = self.allocate_register();
            self.code_expr_into(&expr, ctx, reg)?;
            arg_regs.push(reg.to_string());
        }

        // P4 = "CONCAT:reg1:reg2:..."
        let func_spec = format!("CONCAT:{}", arg_regs.join(":"));

        self.emit(
            OpCode::StringFunc,
            src_reg,
            target_reg,
            0,
            Some(func_spec),
            &format!("r[{}] = CONCAT(...)", target_reg),
        );

        Ok(())
    }

    /// Compile LEFT and RIGHT string functions
    fn compile_func_left_right(
        &mut self,
        func_name: &str,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).len() != 2 {
            return Err(SqawkError::InvalidSqlQuery(format!(
                "{} requires exactly two arguments",
                func_name
            )));
        }

        let str_expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let len_expr = self.extract_function_arg_expr(&func_args(func)[1])?;

        let str_reg = self.allocate_register();
        let len_reg = self.allocate_register();

        self.code_expr_into(&str_expr, ctx, str_reg)?;
        self.code_expr_into(&len_expr, ctx, len_reg)?;

        self.emit(
            OpCode::StringFunc,
            str_reg,
            target_reg,
            len_reg,
            Some(func_name.to_string()),
            &format!(
                "r[{}] = {}(r[{}], r[{}])",
                target_reg, func_name, str_reg, len_reg
            ),
        );

        Ok(())
    }

    /// Compile math functions (ABS, ROUND, CEIL, CEILING, FLOOR)
    fn compile_func_math(
        &mut self,
        func_name: &str,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        let args = func_args(func);
        check_math_func_arity(func_name, args.len())?;

        let expr = self.extract_function_arg_expr(&args[0])?;
        let src_reg = self.allocate_register();

        // Compile the argument
        self.code_expr_into(&expr, ctx, src_reg)?;

        // P3 carries the register holding ROUND's precision, or -1 when the
        // call has no second argument.
        let (prec_reg, desc) = if args.len() == 2 {
            let prec_expr = self.extract_function_arg_expr(&args[1])?;
            let reg = self.allocate_register();
            self.code_expr_into(&prec_expr, ctx, reg)?;
            (
                reg,
                format!(
                    "r[{}] = {}(r[{}], r[{}])",
                    target_reg, func_name, src_reg, reg
                ),
            )
        } else {
            (
                -1,
                format!("r[{}] = {}(r[{}])", target_reg, func_name, src_reg),
            )
        };

        // Emit MathFunc opcode
        self.emit(
            OpCode::MathFunc,
            src_reg,
            target_reg,
            prec_reg,
            Some(func_name.to_string()),
            &desc,
        );

        Ok(())
    }

    /// Compile date/time functions with no arguments (NOW, CURRENT_TIMESTAMP, etc.)
    fn compile_func_datetime_noarg(&mut self, func_name: &str, target_reg: i64) -> SqawkResult<()> {
        self.emit(
            OpCode::DateFunc,
            0, // No source register needed
            target_reg,
            0,
            Some(func_name.to_string()),
            &format!("r[{}] = {}()", target_reg, func_name),
        );

        Ok(())
    }

    /// Compile date/time functions with one argument (DATE, TIME)
    fn compile_func_datetime(
        &mut self,
        func_name: &str,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).is_empty() {
            return Err(SqawkError::InvalidSqlQuery(format!(
                "{} requires one argument",
                func_name
            )));
        }

        let expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let src_reg = self.allocate_register();

        // Compile the argument
        self.code_expr_into(&expr, ctx, src_reg)?;

        // Emit DateFunc opcode
        self.emit(
            OpCode::DateFunc,
            src_reg,
            target_reg,
            0,
            Some(func_name.to_string()),
            &format!("r[{}] = {}(r[{}])", target_reg, func_name, src_reg),
        );

        Ok(())
    }

    /// Compile a function call - dispatches to specialized handlers
    fn compile_function(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        let func_name = Self::get_function_name(func);

        match func_name.as_str() {
            "COALESCE" => self.compile_func_coalesce(func, ctx, target_reg),
            "NULLIF" => self.compile_func_nullif(func, ctx, target_reg),
            "UPPER" | "LOWER" | "TRIM" | "LTRIM" | "RTRIM" | "LENGTH" => {
                self.compile_func_string_simple(&func_name, func, ctx, target_reg)
            }
            "SUBSTR" | "SUBSTRING" => self.compile_func_substr(func, ctx, target_reg),
            "REPLACE" => self.compile_func_replace(func, ctx, target_reg),
            "CONCAT" => self.compile_func_concat(func, ctx, target_reg),
            "LEFT" | "RIGHT" => self.compile_func_left_right(&func_name, func, ctx, target_reg),
            "ABS" | "ROUND" | "CEIL" | "CEILING" | "FLOOR" => {
                self.compile_func_math(&func_name, func, ctx, target_reg)
            }
            "NOW" | "CURRENT_TIMESTAMP" | "CURRENT_DATE" | "CURRENT_TIME" => {
                self.compile_func_datetime_noarg(&func_name, target_reg)
            }
            "DATE" | "TIME" => self.compile_func_datetime(&func_name, func, ctx, target_reg),
            _ => Err(SqawkError::UnsupportedSqlFeature(format!(
                "Unsupported function: {}",
                func_name
            ))),
        }
    }

    /// Extract expression from a function argument
    pub(crate) fn extract_function_arg_expr(&self, arg: &FunctionArg) -> SqawkResult<Expr> {
        match arg {
            FunctionArg::Unnamed(FunctionArgExpr::Expr(expr)) => Ok(expr.clone()),
            FunctionArg::Named {
                arg: FunctionArgExpr::Expr(expr),
                ..
            } => Ok(expr.clone()),
            _ => Err(SqawkError::UnsupportedSqlFeature(
                "Unsupported function argument type".to_string(),
            )),
        }
    }

    /// Compile `expr` into a register, returning that register.
    ///
    /// This is the single expression compiler -- the analogue of SQLite's
    /// `sqlite3ExprCode()`. It is used from every position an expression can
    /// appear in, so a node supported in one position is supported in all of
    /// them. sqawk previously had two: `compile_expr` (no `Identifier` arm at
    /// all) and `compile_projection_expr`/`resolve_column_expr` ("Only column
    /// references supported in SELECT"). That split is why `CASE` and `CAST`
    /// worked in WHERE but not in a SELECT list, and why `SUBSTR` in WHERE
    /// broke on the sqlparser upgrade while `SUBSTR` in a projection did not.
    ///
    /// `into` names the destination register when the caller needs the value
    /// at a specific place -- which is how contiguous blocks for `ResultRow`
    /// and `SorterInsert` are built without the copy-shuffling the old
    /// projection paths did.
    ///
    /// Invariant: on `Ok(reg)`, code has been emitted that defines `reg` on
    /// every path. There is deliberately no arm that returns `Ok` without
    /// emitting -- that bug (an `_` arm that silently emitted nothing, leaving
    /// the register at its default NULL) is why `SELECT name, salary*2 ...
    /// LIMIT 3` returned NULL.
    pub(crate) fn code_expr(
        &mut self,
        expr: &Expr,
        ctx: &NameCtx<'_>,
        into: Option<i64>,
    ) -> SqawkResult<i64> {
        let dest = into.unwrap_or_else(|| self.allocate_register());

        // A value already computed into a register -- an aggregate, or a
        // GROUP BY key after grouping: read the bound register rather than
        // recompiling it (an aggregate is not a scalar function, and a key's
        // columns no longer have a current row).
        if let Some(src) = ctx.lookup_agg(expr) {
            if src != dest {
                self.emit(
                    OpCode::Copy,
                    src,
                    dest,
                    0,
                    None,
                    &format!("r[{}] = {} (r[{}])", dest, expr, src),
                );
            }
            return Ok(dest);
        }

        match expr {
            // Column references resolve through the context, so they work
            // across joins and aliases and are matched case-insensitively.
            Expr::Identifier(ident) => {
                let col = ctx.resolve_unqualified(&ident.value)?;
                let col = ctx.bind(col, &ident.value)?;
                self.emit_column_ref(col, ctx, dest, &ident.value);
            }

            // `table.column` / `alias.column`. The old WHERE compiler had no
            // arm for this at all, so `FROM employees e WHERE e.age > 30`
            // failed on a single-table query.
            Expr::CompoundIdentifier(parts) if parts.len() >= 2 => {
                let qualifier = &parts[parts.len() - 2].value;
                let name = &parts[parts.len() - 1].value;
                let label = format!("{}.{}", qualifier, name);
                let col = ctx.resolve_qualified(qualifier, name)?;
                let col = ctx.bind(col, &label)?;
                self.emit_column_ref(col, ctx, dest, &label);
            }

            Expr::Nested(inner) => {
                return self.code_expr(inner, ctx, Some(dest));
            }

            // Literals resolve against nothing, so they are compiled here
            // rather than delegated. The fallback needs a single FROM source
            // and would otherwise reject a constant in a join condition --
            // `ON a.x = b.y AND b.id > 102` failing on the `102`.
            Expr::Value(ValueWithSpan { value, .. }) => {
                let literal = match value {
                    Value::Number(n, _) => match n.parse::<i64>() {
                        Ok(i) => TableValue::Integer(i),
                        Err(_) => match n.parse::<f64>() {
                            Ok(f) => TableValue::Float(f),
                            Err(_) => TableValue::String(n.clone().into()),
                        },
                    },
                    Value::SingleQuotedString(v) | Value::DoubleQuotedString(v) => {
                        TableValue::String(v.clone().into())
                    }
                    Value::Boolean(b) => TableValue::Boolean(*b),
                    Value::Null => TableValue::Null,
                    other => TableValue::String(other.to_string().into()),
                };
                self.emit_value_literal(dest, &literal)?;
            }

            // String concatenation. sqlparser has always produced this node;
            // there was simply no arm for it, so `a || b` was reported as an
            // unsupported operator. It lowers onto the CONCAT string function
            // the engine already implements.
            Expr::BinaryOp {
                left,
                op: BinaryOperator::StringConcat,
                right,
            } => {
                let left_reg = self.code_expr(left, ctx, None)?;
                let right_reg = self.code_expr(right, ctx, None)?;
                self.emit(
                    OpCode::StringFunc,
                    left_reg,
                    dest,
                    0,
                    Some(format!("CONCAT:{}", right_reg)),
                    &format!("r[{}] = r[{}] || r[{}]", dest, left_reg, right_reg),
                );
            }

            // Logical AND / OR with SQL three-valued logic: both operands are
            // evaluated and combined by the And / Or opcodes, so
            // `NULL AND 1` is NULL and `NULL OR 1` is 1. The old
            // short-circuit form collapsed UNKNOWN to false, which made
            // `NOT (a OR b)` true for a row where `a` was NULL.
            Expr::BinaryOp {
                left,
                op: op @ (BinaryOperator::And | BinaryOperator::Or),
                right,
            } => {
                let left_reg = self.code_expr(left, ctx, None)?;
                let right_reg = self.code_expr(right, ctx, None)?;
                let opcode = if matches!(op, BinaryOperator::And) {
                    OpCode::And
                } else {
                    OpCode::Or
                };
                self.emit(
                    opcode,
                    left_reg,
                    right_reg,
                    dest,
                    None,
                    &format!("r[{}] = r[{}] {:?} r[{}]", dest, left_reg, op, right_reg),
                );
            }

            // Arithmetic and comparison operators, compiled here rather than
            // delegated, so the name-resolution context propagates into the
            // operands. Delegating rebuilt a bare single-table context and
            // dropped any aggregate bindings, which is what made
            // `SUM(salary) + 1` report SUM as an unknown scalar function.
            Expr::BinaryOp { left, op, right }
                if matches!(
                    op,
                    BinaryOperator::Plus
                        | BinaryOperator::Minus
                        | BinaryOperator::Multiply
                        | BinaryOperator::Divide
                        | BinaryOperator::Modulo
                        | BinaryOperator::Gt
                        | BinaryOperator::Lt
                        | BinaryOperator::GtEq
                        | BinaryOperator::LtEq
                        | BinaryOperator::Eq
                        | BinaryOperator::NotEq
                ) =>
            {
                let left_reg = self.code_expr(left, ctx, None)?;
                let right_reg = self.code_expr(right, ctx, None)?;
                let opcode = match op {
                    BinaryOperator::Plus => OpCode::Add,
                    BinaryOperator::Minus => OpCode::Subtract,
                    BinaryOperator::Multiply => OpCode::Multiply,
                    BinaryOperator::Divide => OpCode::Divide,
                    BinaryOperator::Modulo => OpCode::Remainder,
                    BinaryOperator::Gt => OpCode::Gt,
                    BinaryOperator::Lt => OpCode::Lt,
                    BinaryOperator::GtEq => OpCode::Ge,
                    BinaryOperator::LtEq => OpCode::Le,
                    BinaryOperator::Eq => OpCode::Eq,
                    BinaryOperator::NotEq => OpCode::Ne,
                    _ => unreachable!("guarded above"),
                };
                self.emit(
                    opcode,
                    left_reg,
                    right_reg,
                    dest,
                    None,
                    &format!("r[{}] = r[{}] {:?} r[{}]", dest, left_reg, op, right_reg),
                );
            }

            // Logical negation, including NULL propagation. Previously
            // unsupported in any position.
            Expr::UnaryOp {
                op: UnaryOperator::Not,
                expr: inner,
            } => {
                let inner_reg = self.code_expr(inner, ctx, None)?;
                self.emit(
                    OpCode::Not,
                    inner_reg,
                    dest,
                    0,
                    None,
                    &format!("r[{}] = NOT r[{}]", dest, inner_reg),
                );
            }

            // Function calls resolve their arguments in the CALLER's scope.
            //
            // Reaching them through the single-source fallback rebuilt a
            // context containing only the innermost table, so inside a
            // correlated subquery `UPPER(e.department)` silently resolved
            // `e.department` against the SUBQUERY table -- making both sides of
            // a comparison identical and matching every row.
            Expr::Function(func) => {
                self.compile_function(func, ctx, dest)?;
            }

            // TRIM / CEIL / FLOOR are their own Expr variants rather than
            // Function calls. They were previously handled only inside the
            // projection path, so they worked in a SELECT list and failed in
            // WHERE -- the same asymmetry SUBSTR had.
            Expr::Trim {
                expr: inner,
                trim_where: None,
                trim_what: None,
                ..
            } => {
                let src = self.code_expr(inner, ctx, None)?;
                self.emit(
                    OpCode::StringFunc,
                    src,
                    dest,
                    0,
                    Some("TRIM".to_string()),
                    &format!("r[{}] = TRIM(r[{}])", dest, src),
                );
            }
            Expr::Ceil { expr: inner, field } => {
                check_ceil_floor_field("CEIL", field)?;
                let src = self.code_expr(inner, ctx, None)?;
                self.emit(
                    OpCode::MathFunc,
                    src,
                    dest,
                    -1,
                    Some("CEIL".to_string()),
                    &format!("r[{}] = CEIL(r[{}])", dest, src),
                );
            }
            Expr::Floor { expr: inner, field } => {
                check_ceil_floor_field("FLOOR", field)?;
                let src = self.code_expr(inner, ctx, None)?;
                self.emit(
                    OpCode::MathFunc,
                    src,
                    dest,
                    -1,
                    Some("FLOOR".to_string()),
                    &format!("r[{}] = FLOOR(r[{}])", dest, src),
                );
            }

            Expr::UnaryOp {
                op: UnaryOperator::Minus,
                expr: inner,
            } => {
                // 0 - value, so integer and float operands keep their type.
                let inner_reg = self.code_expr(inner, ctx, None)?;
                let zero_reg = self.allocate_register();
                self.emit(OpCode::Integer, 0, zero_reg, 0, None, "0 for negation");
                self.emit(
                    OpCode::Subtract,
                    zero_reg,
                    inner_reg,
                    dest,
                    None,
                    &format!("r[{}] = -r[{}]", dest, inner_reg),
                );
            }
            Expr::UnaryOp {
                op: UnaryOperator::Plus,
                expr: inner,
            } => {
                return self.code_expr(inner, ctx, Some(dest));
            }

            // Predicates are values like any other: 1, 0, or NULL for
            // UNKNOWN. Filters (WHERE / ON / HAVING) test the result with
            // IfZ, which rejects NULL along with 0.
            Expr::IsNull(inner) | Expr::IsNotNull(inner) => {
                let src = self.code_expr(inner, ctx, None)?;
                self.emit(
                    OpCode::IsNull,
                    src,
                    dest,
                    0,
                    None,
                    &format!("r[{}] = (r[{}] IS NULL)", dest, src),
                );
                if matches!(expr, Expr::IsNotNull(_)) {
                    self.emit(OpCode::Not, dest, dest, 0, None, "IS NOT NULL");
                }
            }
            Expr::Like {
                negated,
                expr: inner,
                pattern,
                ..
            } => self.compile_like_pattern(inner, pattern, *negated, false, ctx, dest)?,
            Expr::ILike {
                negated,
                expr: inner,
                pattern,
                ..
            } => self.compile_like_pattern(inner, pattern, *negated, true, ctx, dest)?,
            Expr::Between {
                expr: inner,
                negated,
                low,
                high,
            } => self.compile_between(inner, low, high, *negated, ctx, dest)?,
            Expr::InList {
                expr: inner,
                list,
                negated,
            } => self.compile_in_list(inner, list, *negated, ctx, dest)?,
            Expr::InSubquery {
                expr: inner,
                subquery,
                negated,
            } => {
                let values = self.evaluate_in_subquery_values(subquery)?;
                if values.is_empty() {
                    self.emit_empty_in(*negated, dest);
                } else {
                    let x = self.code_expr(inner, ctx, None)?;
                    let item = self.allocate_register();
                    let hit = self.allocate_register();
                    self.emit(OpCode::Integer, 0, dest, 0, None, "IN subquery init");
                    for value in &values {
                        self.emit_value_literal(item, value)?;
                        self.emit_in_step(x, item, hit, dest);
                    }
                    if *negated {
                        self.emit(OpCode::Not, dest, dest, 0, None, "NOT IN");
                    }
                }
            }
            Expr::Exists { subquery, negated } => {
                let outer_refs = self.detect_outer_references(subquery, ctx);
                if outer_refs.is_empty() {
                    let exists = self.evaluate_exists_subquery(subquery, *negated)?;
                    self.emit(
                        OpCode::Integer,
                        exists as i64,
                        dest,
                        0,
                        None,
                        &format!("r[{}] = {} (EXISTS result)", dest, exists as i64),
                    );
                } else {
                    self.compile_correlated_exists_subquery(
                        subquery,
                        *negated,
                        ctx,
                        &outer_refs,
                        dest,
                    )?;
                }
            }
            Expr::Subquery(subquery) => {
                let outer_refs = self.detect_outer_references(subquery, ctx);
                if outer_refs.is_empty() {
                    let value = self.evaluate_scalar_subquery(subquery)?;
                    self.emit_value_literal(dest, &value)?;
                } else {
                    self.compile_correlated_scalar_subquery(subquery, ctx, &outer_refs, dest)?;
                }
            }

            Expr::Case {
                operand,
                conditions,
                else_result,
                ..
            } => self.compile_case(
                operand.as_deref(),
                conditions,
                else_result.as_deref(),
                ctx,
                dest,
            )?,
            Expr::Cast {
                expr: inner,
                data_type,
                ..
            } => {
                let src = self.code_expr(inner, ctx, None)?;
                let type_name = self.sql_data_type_to_string(data_type);
                self.emit(
                    OpCode::Cast,
                    src,
                    dest,
                    0,
                    Some(type_name.clone()),
                    &format!("r[{}] = CAST(r[{}] AS {})", dest, src, type_name),
                );
            }
            // `SUBSTR(x, 1, 3)` parses as `Expr::Substring`, not as a
            // `Expr::Function`, so it needs an arm of its own.
            Expr::Substring {
                expr: inner,
                substring_from,
                substring_for,
                ..
            } => self.compile_substring(
                inner,
                substring_from.as_deref(),
                substring_for.as_deref(),
                ctx,
                dest,
            )?,

            other => {
                return Err(SqawkError::UnsupportedSqlFeature(format!(
                    "Unsupported expression: {}",
                    other
                )))
            }
        }

        Ok(dest)
    }

    /// `IN ()` over an empty set: false, or true for NOT IN -- even for a
    /// NULL left operand, as in SQLite.
    fn emit_empty_in(&mut self, negated: bool, dest: i64) {
        self.emit(
            OpCode::Integer,
            negated as i64,
            dest,
            0,
            None,
            &format!("r[{}] = {} (empty IN set)", dest, negated as i64),
        );
    }

    /// One element of an IN test: `dest = dest OR (x = item)`.
    ///
    /// Folding with three-valued OR gives exactly SQL's IN semantics: 1 if
    /// any element equals `x`; otherwise NULL if `x` or any element is NULL;
    /// otherwise 0.
    fn emit_in_step(&mut self, x: i64, item: i64, hit: i64, dest: i64) {
        self.emit(
            OpCode::Eq,
            x,
            item,
            hit,
            None,
            &format!("r[{}] = (r[{}] == r[{}])", hit, x, item),
        );
        self.emit(
            OpCode::Or,
            dest,
            hit,
            dest,
            None,
            &format!("r[{}] = r[{}] OR r[{}] (IN)", dest, dest, hit),
        );
    }

    /// Emit whatever loads a resolved column into `dest`.
    fn emit_column_ref(&mut self, col: ColumnRef, ctx: &NameCtx<'_>, dest: i64, label: &str) {
        match col {
            ColumnRef::Cursor { cursor, col } => self.emit(
                OpCode::Column,
                cursor,
                col as i64,
                dest,
                None,
                &format!("r[{}] = {} (column {})", dest, label, col),
            ),
            ColumnRef::Register(src) => {
                if src != dest {
                    self.emit(
                        OpCode::Copy,
                        src,
                        dest,
                        0,
                        None,
                        &format!("r[{}] = {} (r[{}])", dest, label, src),
                    );
                }
            }
            // COALESCE over the merged columns, leftmost first.
            ColumnRef::Using(i) => {
                let refs = ctx.using[i].refs.clone();
                let done = self.label();
                let is_null = self.allocate_register();
                for (n, (cursor, col)) in refs.iter().enumerate() {
                    self.emit(
                        OpCode::Column,
                        *cursor,
                        *col as i64,
                        dest,
                        None,
                        &format!("r[{}] = {} (USING column, source {})", dest, label, n),
                    );
                    if n + 1 < refs.len() {
                        self.emit(OpCode::IsNull, dest, is_null, 0, None, "");
                        self.emit_jump_to(OpCode::IfZ, is_null, done, 0, None, "not NULL: done");
                    }
                }
                self.resolve(done);
            }
        }
    }

    /// `code_expr` with the argument order the function compilers use.
    fn code_expr_into(
        &mut self,
        expr: &Expr,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        self.code_expr(expr, ctx, Some(target_reg)).map(|_| ())
    }

    /// Convert a SQL DataType to a string representation for the VM
    fn sql_data_type_to_string(&self, data_type: &SqlDataType) -> String {
        match data_type {
            SqlDataType::Int(_)
            | SqlDataType::Integer(_)
            | SqlDataType::BigInt(_)
            | SqlDataType::SmallInt(_) => "INTEGER".to_string(),
            SqlDataType::Real | SqlDataType::Float(_) | SqlDataType::Double(_) => {
                "REAL".to_string()
            }
            SqlDataType::Text
            | SqlDataType::Varchar(_)
            | SqlDataType::Char(_)
            | SqlDataType::String(_) => "TEXT".to_string(),
            SqlDataType::Boolean => "BOOLEAN".to_string(),
            _ => format!("{:?}", data_type),
        }
    }

    /// Get a normalized table name from an ObjectName
    pub(crate) fn get_table_name(&self, name: &ObjectName) -> SqawkResult<String> {
        if name.0.is_empty() {
            return Err(SqawkError::InvalidSqlQuery("Empty table name".to_string()));
        }

        // Use the last part of the object name as the table name
        // (schemas and catalogs are ignored for now)
        Ok(object_name_last(name))
    }

    /// Emit post-processing ORDER BY / LIMIT / OFFSET over the result set.
    ///
    /// Used by the paths that produce rows without going through the
    /// cursor-based sorter -- GROUP BY, plain aggregates and joins. Those
    /// paths previously dropped ORDER BY and LIMIT on the floor: `query` was
    /// simply never passed to them, and for joins the code said so outright
    /// ("ORDER BY support for JOINs [...] isn't fully implemented. For now,
    /// compile the JOIN and skip ORDER BY").
    ///
    /// ORDER BY keys are matched against the SELECT list, since after
    /// aggregation the only columns that still exist are the projected ones.
    fn emit_result_post_processing(&mut self, select: &Select, query: &Query) -> SqawkResult<()> {
        // ORDER BY
        let order_by = query_order_by(query);
        if !order_by.is_empty() {
            let mut keys: Vec<String> = Vec::with_capacity(order_by.len());
            for ob in order_by {
                let out_columns = self.program.result_schema.columns.len();
                let pos = match Self::order_by_ordinal(&ob.expr, out_columns)? {
                    Some(idx) => idx,
                    None => Self::projection_position(&select.projection, &ob.expr)
                        .or_else(|| self.result_column_position(&ob.expr))
                        .ok_or_else(|| {
                            SqawkError::InvalidSqlQuery(format!(
                                "ORDER BY expression must appear in the SELECT list: {}",
                                ob.expr
                            ))
                        })?,
                };
                keys.push(format!(
                    "{}:{}",
                    pos,
                    if order_by_is_asc(ob) { "asc" } else { "desc" }
                ));
            }
            let spec = keys.join(",");
            self.emit(
                OpCode::SortResults,
                0,
                0,
                0,
                Some(spec.clone()),
                &format!("ORDER BY {}", spec),
            );
        }

        // LIMIT / OFFSET
        let limit = match query_limit(query) {
            Some(e) => Some(Self::const_i64(e, "LIMIT")?),
            None => None,
        };
        let offset = match query_offset(query) {
            Some(e) => Self::const_i64(e, "OFFSET")?,
            None => 0,
        };
        if limit.is_some() || offset > 0 {
            self.emit(
                OpCode::Limit,
                limit.unwrap_or(i64::MAX),
                offset,
                0,
                None,
                &format!("Limit {:?} offset {}", limit, offset),
            );
        }
        Ok(())
    }

    /// Position of `needle` within the SELECT list, if it appears there.
    ///
    /// Matches an alias by name, and otherwise compares the rendered
    /// expression, so `ORDER BY COUNT(*)` finds `COUNT(*)` in the projection
    /// and `ORDER BY department` finds a bare column.
    fn projection_position(projection: &[SelectItem], needle: &Expr) -> Option<usize> {
        let want = needle.to_string().to_ascii_lowercase();
        for (i, item) in projection.iter().enumerate() {
            let matches = match item {
                SelectItem::UnnamedExpr(e) => e.to_string().to_ascii_lowercase() == want,
                SelectItem::ExprWithAlias { expr, alias } => {
                    alias.value.to_ascii_lowercase() == want
                        || expr.to_string().to_ascii_lowercase() == want
                }
                _ => false,
            };
            if matches {
                return Some(i);
            }
        }
        None
    }

    /// A positional ORDER BY key (`ORDER BY 2`) as a zero-based output index.
    ///
    /// SQL numbers these from 1 against the SELECT list. Compiling such a key
    /// as an ordinary expression yields a CONSTANT, giving every row the same
    /// sort key and silently turning the sort into a no-op -- worse than the
    /// old code, which at least rejected the form.
    fn order_by_ordinal(expr: &Expr, out_columns: usize) -> SqawkResult<Option<usize>> {
        let n = match expr {
            Expr::Value(ValueWithSpan {
                value: Value::Number(n, _),
                ..
            }) => n,
            _ => return Ok(None),
        };
        let idx: usize = n.parse().map_err(|_| {
            SqawkError::InvalidSqlQuery(format!("Invalid ORDER BY position: {}", n))
        })?;
        if idx == 0 || idx > out_columns {
            return Err(SqawkError::InvalidSqlQuery(format!(
                "ORDER BY position {} is out of range (1..{})",
                idx, out_columns
            )));
        }
        Ok(Some(idx - 1))
    }

    /// Position of `expr` among the RESULT columns, by name.
    ///
    /// The projection-list search cannot see through a wildcard: `SELECT *`
    /// contributes one `SelectItem::Wildcard` while producing many output
    /// columns, so ordering a `SELECT *` join by any column found nothing and
    /// was rejected. The result schema is already built by the time
    /// post-processing is emitted and names every output column, including
    /// the expanded ones.
    ///
    /// Matches a qualified name exactly first, then falls back to the bare
    /// column name, so `ORDER BY name` finds an output column called `c.name`.
    fn result_column_position(&self, expr: &Expr) -> Option<usize> {
        let want = match expr {
            Expr::Identifier(ident) => ident.value.to_ascii_lowercase(),
            Expr::CompoundIdentifier(parts) if parts.len() >= 2 => format!(
                "{}.{}",
                parts[parts.len() - 2].value.to_ascii_lowercase(),
                parts[parts.len() - 1].value.to_ascii_lowercase()
            ),
            _ => return None,
        };

        let cols = &self.program.result_schema.columns;
        if let Some(i) = cols
            .iter()
            .position(|c| c.name.to_ascii_lowercase() == want)
        {
            return Some(i);
        }
        // Unqualified key against qualified output columns, or vice versa.
        let bare = want.rsplit('.').next().unwrap_or(&want).to_string();
        cols.iter().position(|c| {
            let n = c.name.to_ascii_lowercase();
            n == bare || n.rsplit('.').next().map(|x| x == bare).unwrap_or(false)
        })
    }

    /// Evaluate a LIMIT/OFFSET operand, which must be a constant.
    fn const_i64(expr: &Expr, what: &str) -> SqawkResult<i64> {
        match expr {
            Expr::Value(ValueWithSpan {
                value: Value::Number(n, _),
                ..
            }) => n
                .parse::<i64>()
                .map_err(|_| SqawkError::InvalidSqlQuery(format!("Invalid {} value: {}", what, n))),
            _ => Err(SqawkError::UnsupportedSqlFeature(format!(
                "Only constant {} supported",
                what
            ))),
        }
    }

    pub(crate) fn get_column_name_from_expr(&self, expr: &Expr) -> String {
        match expr {
            Expr::Identifier(ident) => ident.value.clone(),
            Expr::CompoundIdentifier(parts) => {
                parts.last().map(|p| p.value.clone()).unwrap_or_default()
            }
            Expr::Function(func) => {
                // For aggregate functions, return just the function name (e.g., "COUNT" not "COUNT(*)")
                // For other functions, include arguments for clarity
                let func_name = func.name.to_string().to_uppercase();
                if matches!(func_name.as_str(), "COUNT" | "SUM" | "AVG" | "MIN" | "MAX") {
                    func_name
                } else if let Some(FunctionArg::Unnamed(FunctionArgExpr::Wildcard)) =
                    func_args(func).first()
                {
                    format!("{}(*)", func_name)
                } else if let Some(FunctionArg::Unnamed(FunctionArgExpr::Expr(arg_expr))) =
                    func_args(func).first()
                {
                    // ROUND's precision has to appear in the name, or
                    // `SELECT ROUND(a, 1), ROUND(a, 3)` yields two columns
                    // both called `ROUND(a)` and the second is unaddressable.
                    // The precision is rendered from the AST rather than named
                    // recursively, so a literal shows as `1` not `expr`.
                    if func_name == "ROUND" {
                        if let Some(FunctionArg::Unnamed(FunctionArgExpr::Expr(prec))) =
                            func_args(func).get(1)
                        {
                            return format!(
                                "{}({}, {})",
                                func_name,
                                self.get_column_name_from_expr(arg_expr),
                                prec
                            );
                        }
                    }
                    format!(
                        "{}({})",
                        func_name,
                        self.get_column_name_from_expr(arg_expr)
                    )
                } else {
                    format!("{}()", func_name)
                }
            }
            // SUBSTR/SUBSTRING is its own Expr variant rather than a Function,
            // so it needs an arm here to keep the descriptive column name
            // (`SUBSTR(name)`) instead of falling through to `expr`.
            Expr::Substring { expr, .. } => {
                format!("SUBSTR({})", self.get_column_name_from_expr(expr))
            }
            _ => "expr".to_string(),
        }
    }

    /// Infer the data type of an expression
    pub(crate) fn infer_expr_type(&self, expr: &Expr, ctx: &NameCtx<'_>) -> DataType {
        let column_type = |col: SqawkResult<ColumnRef>| -> DataType {
            let (cursor, idx) = match col {
                Ok(ColumnRef::Cursor { cursor, col }) => (cursor, col),
                Ok(ColumnRef::Using(i)) => ctx.using[i].refs[0],
                _ => return DataType::Text,
            };
            ctx.srcs
                .iter()
                .chain(&ctx.outer)
                .find(|s| s.cursor == cursor)
                .and_then(|s| s.table.column_metadata().get(idx))
                .map(|m| m.data_type)
                .unwrap_or(DataType::Text)
        };
        match expr {
            Expr::Identifier(ident) => column_type(ctx.resolve_unqualified(&ident.value)),
            Expr::CompoundIdentifier(parts) if parts.len() >= 2 => column_type(
                ctx.resolve_qualified(&parts[parts.len() - 2].value, &parts[parts.len() - 1].value),
            ),
            Expr::Function(func) => {
                let func_name = func.name.to_string().to_uppercase();
                match func_name.as_str() {
                    "COUNT" => DataType::Integer,
                    "SUM" | "AVG" => {
                        // SUM/AVG preserves numeric type, defaults to Float for AVG
                        if func_name == "AVG" {
                            DataType::Float
                        } else {
                            // Try to infer from argument
                            if let Some(FunctionArg::Unnamed(FunctionArgExpr::Expr(arg))) =
                                func_args(func).first()
                            {
                                let arg_type = self.infer_expr_type(arg, ctx);
                                if matches!(arg_type, DataType::Integer) {
                                    return DataType::Integer;
                                }
                            }
                            DataType::Float
                        }
                    }
                    "MIN" | "MAX" => {
                        // MIN/MAX preserves the type of the argument
                        if let Some(FunctionArg::Unnamed(FunctionArgExpr::Expr(arg))) =
                            func_args(func).first()
                        {
                            return self.infer_expr_type(arg, ctx);
                        }
                        DataType::Text
                    }
                    "UPPER" | "LOWER" | "TRIM" | "LTRIM" | "RTRIM" | "SUBSTR" | "REPLACE" => {
                        DataType::Text
                    }
                    "COALESCE" => {
                        // COALESCE returns the type of its first non-null argument
                        if let Some(FunctionArg::Unnamed(FunctionArgExpr::Expr(arg))) =
                            func_args(func).first()
                        {
                            return self.infer_expr_type(arg, ctx);
                        }
                        DataType::Text
                    }
                    _ => DataType::Text,
                }
            }
            Expr::Value(ValueWithSpan { value: val, .. }) => {
                match val {
                    Value::Number(_, _) => DataType::Integer, // Could be Float, but Integer is common
                    Value::SingleQuotedString(_) | Value::DoubleQuotedString(_) => DataType::Text,
                    Value::Boolean(_) => DataType::Boolean,
                    Value::Null => DataType::Text, // NULL doesn't have a type, default to Text
                    _ => DataType::Text,
                }
            }
            Expr::BinaryOp { left, op, right: _ } => {
                // Arithmetic ops return numeric, comparisons return boolean
                match op {
                    BinaryOperator::Plus
                    | BinaryOperator::Minus
                    | BinaryOperator::Multiply
                    | BinaryOperator::Divide
                    | BinaryOperator::Modulo => self.infer_expr_type(left, ctx),
                    BinaryOperator::Eq
                    | BinaryOperator::NotEq
                    | BinaryOperator::Lt
                    | BinaryOperator::LtEq
                    | BinaryOperator::Gt
                    | BinaryOperator::GtEq
                    | BinaryOperator::And
                    | BinaryOperator::Or => DataType::Boolean,
                    BinaryOperator::StringConcat => DataType::Text,
                    _ => DataType::Text,
                }
            }
            Expr::Case {
                conditions,
                else_result,
                ..
            } => {
                // CASE returns the type of its first result
                if let Some(first) = conditions.first() {
                    return self.infer_expr_type(&first.result, ctx);
                }
                if let Some(else_expr) = else_result {
                    return self.infer_expr_type(else_expr, ctx);
                }
                DataType::Text
            }
            Expr::Cast { data_type, .. } => {
                // CAST returns the target type
                match data_type {
                    SqlDataType::Int(_)
                    | SqlDataType::Integer(_)
                    | SqlDataType::BigInt(_)
                    | SqlDataType::SmallInt(_) => DataType::Integer,
                    SqlDataType::Real | SqlDataType::Float(_) | SqlDataType::Double(_) => {
                        DataType::Float
                    }
                    SqlDataType::Boolean => DataType::Boolean,
                    _ => DataType::Text,
                }
            }
            _ => DataType::Text, // Default
        }
    }

    /// Check if a SELECT projection contains aggregate functions
    fn has_aggregates(&self, projection: &[SelectItem]) -> bool {
        for item in projection {
            match item {
                SelectItem::UnnamedExpr(expr) | SelectItem::ExprWithAlias { expr, .. }
                    if self.is_aggregate_expr(expr) =>
                {
                    return true;
                }
                _ => {}
            }
        }
        false
    }

    /// Whether `expr` is directly an aggregate call.
    ///
    /// A free function so the grouped-projection planner can use it without a
    /// compiler borrow.
    pub(crate) fn is_aggregate_call(expr: &Expr) -> bool {
        match expr {
            Expr::Function(func) if func.over.is_none() => {
                let name = func.name.to_string().to_uppercase();
                matches!(name.as_str(), "COUNT" | "SUM" | "AVG" | "MIN" | "MAX")
            }
            _ => false,
        }
    }

    /// Check if an expression is or CONTAINS an aggregate function.
    ///
    /// Recursive: this used to match only a top-level call, so
    /// `SELECT SUM(salary) + 1` was not recognised as an aggregate query and
    /// took the plain table-scan path, where SUM is not a known scalar
    /// function.
    fn is_aggregate_expr(&self, expr: &Expr) -> bool {
        if Self::is_aggregate_call(expr) {
            return true;
        }
        expr_children(expr)
            .is_some_and(|children| children.into_iter().any(|c| self.is_aggregate_expr(c)))
    }

    /// Check if the projection contains any window functions
    fn has_window_functions(&self, projection: &[SelectItem]) -> bool {
        for item in projection {
            match item {
                SelectItem::UnnamedExpr(expr) | SelectItem::ExprWithAlias { expr, .. }
                    if self.is_window_expr(expr) =>
                {
                    return true;
                }
                _ => {}
            }
        }
        false
    }

    /// Check if an expression is a window function (has OVER clause)
    fn is_window_expr(&self, expr: &Expr) -> bool {
        match expr {
            Expr::Function(func) => func.over.is_some(),
            _ => false,
        }
    }

    /// Get the window function type code
    pub(crate) fn get_window_func_type(&self, name: &str) -> i64 {
        match name.to_uppercase().as_str() {
            "ROW_NUMBER" => 0,
            "RANK" => 1,
            "DENSE_RANK" => 2,
            "LAG" => 3,
            "LEAD" => 4,
            "SUM" => 5,
            "AVG" => 6,
            "COUNT" => 7,
            "MIN" => 8,
            "MAX" => 9,
            _ => 0,
        }
    }
}
